"aphasia\"][data-contrast=\"high\"]{\n  --bg:#0B1017;--card:#151C26;--ink:#F2F6FB;--ink-soft:#A9B6C6;--line:rgba(255,255,255,.16);\n  background:\n    radial-gradient(1000px 560px at 82% -12%, rgba(124,110,220,.16), transparent 62%),\n    radial-gradient(820px 520px at -12% 16%, rgba(66,178,200,.13), transparent 58%),\n    #0B1017 !important;\n}\nbody[data-theme=\"adult\"][data-contrast=\"high\"] .main-header,body[data-theme=\"aphasia\"][data-contrast=\"high\"] .main-header,\nbody[data-theme=\"adult\"][data-contrast=\"high\"] .hero-panel,body[data-theme=\"aphasia\"][data-contrast=\"high\"] .hero-panel,\nbody[data-theme=\"adult\"][data-contrast=\"high\"] .path,body[data-theme=\"aphasia\"][data-contrast=\"high\"] .path,\nbody[data-theme=\"adult\"][data-contrast=\"high\"] .catcard,body[data-theme=\"aphasia\"][data-contrast=\"high\"] .catcard,\nbody[data-theme=\"adult\"][data-contrast=\"high\"] .typebox,body[data-theme=\"aphasia\"][data-contrast=\"high\"] .typebox,\nbody[data-theme=\"adult\"][data-contrast=\"high\"] .phrase,body[data-theme=\"aphasia\"][data-contrast=\"high\"] .phrase,\nbody[data-theme=\"adult\"][data-contrast=\"high\"] .card,body[data-theme=\"aphasia\"][data-contrast=\"high\"] .card,\nbody[data-theme=\"adult\"][data-contrast=\"high\"] .progress-card,body[data-theme=\"adult\"][data-contrast=\"high\"] .scenario-card{\n  background:#151C26 !important;color:#F2F6FB;border:1px solid rgba(255,255,255,.14);\n  box-shadow:0 6px 22px rgba(0,0,0,.45);\n}\nbody[data-contrast=\"high\"] .brand-name,body[data-contrast=\"high\"] .hero-center h1,body[data-contrast=\"high\"] .path .tx h3,body[data-contrast=\"high\"] .support-card strong,body[data-contrast=\"high\"] .scenario-card h3,body[data-contrast=\"high\"] .catcard .cn,body[data-contrast=\"high\"] .typebox-title h2{color:var(--ink)}\nbody[data-contrast=\"high\"] .access-btn,body[data-contrast=\"high\"] .text-size-group,body[data-contrast=\"high\"] .modepick{background:var(--card);border:1px solid rgba(255,255,255,.14);color:var(--ink)}\n/* quick bar: deep tinted surfaces so emoji sit comfortably */\nbody[data-theme=\"aphasia\"][data-contrast=\"high\"] .quick,\nbody[data-theme=\"adult\"][data-contrast=\"high\"] .quick{\n  border:1px solid rgba(255,255,255,.14) !important;box-shadow:0 4px 16px rgba(0,0,0,.4) !important;\n}\nbody[data-theme=\"aphasia\"][data-contrast=\"high\"] .quick:nth-child(1){background:#163227 !important;color:#8FE7B8 !important}\nbody[data-theme=\"aphasia\"][data-contrast=\"high\"] .quick:nth-child(2){background:#3A2020 !important;color:#F5AFA2 !important}\nbody[data-theme=\"aphasia\"][data-contrast=\"high\"] .quick:nth-child(3){background:#14303A !important;color:#8ED8EC !important}\nbody[data-theme=\"aphasia\"][data-contrast=\"high\"] .quick:nth-child(4){background:#3A3218 !important;color:#F3D48A !important}\n/* selected mode pill keeps a soft glow instead of a hard white edge */\nbody[data-contrast=\"high\"] .modepick .mode.active{\n  background:linear-gradient(92deg,rgba(66,178,200,.28),rgba(124,110,220,.28)) !important;\n  color:#FFFFFF !important;box-shadow:0 0 0 1px rgba(120,190,230,.35),0 0 18px rgba(90,160,220,.22) !important;\n}\n\n@media (max-width:980px){\n  .kid-home .hero-grid{grid-template-columns:170px minmax(0,1fr)}.kid-home .progress-card{grid-column:1/-1}.adult-home .hero-grid{grid-template-columns:1fr}.adult-home .hero-center{text-align:center;padding-left:0}.adult-home .hero-center p{margin-left:auto}\n  .home-layout{grid-template-columns:1fr}.side-stack{display:grid;grid-template-columns:repeat(2,minmax(0,1fr))}.support-grid{grid-template-columns:repeat(2,minmax(0,1fr))}\n}\n@media (max-width:720px){\n  .app{padding:10px 10px 104px;gap:12px}.main-header{border-radius:18px;padding:10px;align-items:flex-start}.brand-name{font-size:1rem}.brand-mark{width:42px;height:42px}.accessbar{gap:5px}.access-btn{min-width:58px;padding:5px 6px}.access-btn small{font-size:.6rem}.text-size-group .ts-label{display:none}.text-size-group{padding:4px}\n  .hero-panel{padding:18px 14px}.kid-home .hero-grid{grid-template-columns:1fr}.journey-guide{flex-direction:row;text-align:left;justify-content:center}.leo-hero-frame{width:112px;height:118px;flex:none}.leo-hero-img{width:110px;height:118px}.guide-bubble{max-width:230px}.kid-home .progress-card{grid-column:auto}.progress-card{max-width:360px;margin:0 auto;width:100%}\n  .steps-grid{grid-template-columns:1fr}.path.step-card{min-height:124px}.side-stack{grid-template-columns:1fr}.support-grid{grid-template-columns:1fr 1fr}.aphasia-home .catgrid{grid-template-columns:repeat(2,minmax(0,1fr))}.aphasia-home .quickbar{grid-template-columns:repeat(2,minmax(0,1fr))}.aphasia-home .typerow{flex-wrap:wrap}.aphasia-home .typerow input{flex-basis:100%}.aphasia-home .typerow .showbtn,.aphasia-home .typerow .saybtn{height:52px;flex:1}.typebox-title{display:block}.typebox-title p{margin-top:2px}\n}\n@media (max-width:430px){\n  .main-header{display:block}.accessbar{margin-top:9px;justify-content:space-between}.access-btn{flex:1}.modepick{display:grid;grid-template-columns:1fr}.modepick .mode{min-height:44px}.path.step-card{grid-template-columns:54px minmax(0,1fr)}.path.step-card .badge{width:54px;height:54px}.path.step-card .st{grid-column:2}.support-grid{grid-template-columns:1fr}.aphasia-home .catgrid{grid-template-columns:1fr}.aphasia-home .aph-actions{grid-template-columns:1fr}\n}\n\n\n/* ================= DARK / LIGHT MODE COMPLETION PATCH =================\n   Applies the high-contrast dark display consistently to every mode,\n   preserves the official Voice icon inside a visible pale bubble,\n   and fixes secondary-screen text and Back controls. */\nbody[data-contrast=\"high\"]{\n  --bg:#0B1017;\n  --card:#151C26;\n  --ink:#F4F7FB;\n  --ink-soft:#B5C0CF;\n  --line:rgba(255,255,255,.18);\n  --shadow:0 8px 26px rgba(0,0,0,.42);\n  --mvj-navy:#F4F7FB;\n  --mvj-purple-deep:#E7DEFF;\n  --mvj-soft:#151C26;\n  color-scheme:dark;\n  color:var(--ink);\n  background:\n    radial-gradient(1000px 560px at 82% -12%,rgba(124,110,220,.17),transparent 62%),\n    radial-gradient(820px 520px at -12% 16%,rgba(66,178,200,.13),transparent 58%),\n    #0B1017 !important;\n}\n\n/* Main surfaces in Learning, English Practice, My Words, and every subpage */\nbody[data-contrast=\"high\"] .main-header,\nbody[data-contrast=\"high\"] .hero-panel,\nbody[data-contrast=\"high\"] .modepick,\nbody[data-contrast=\"high\"] .path,\nbody[data-contrast=\"high\"] .path.step-card,\nbody[data-contrast=\"high\"] .support-card,\nbody[data-contrast=\"high\"] .scenario-card,\nbody[data-contrast=\"high\"] .scenario-item,\nbody[data-contrast=\"high\"] .progress-card,\nbody[data-contrast=\"high\"] .card,\nbody[data-contrast=\"high\"] .stat,\nbody[data-contrast=\"high\"] .catcard,\nbody[data-contrast=\"high\"] .phrase,\nbody[data-contrast=\"high\"] .typebox,\nbody[data-contrast=\"high\"] .heard,\nbody[data-contrast=\"high\"] .overlay .panel,\nbody[data-contrast=\"high\"] .strip,\nbody[data-contrast=\"high\"] .step,\nbody[data-contrast=\"high\"] .slots .sl,\nbody[data-contrast=\"high\"] .wordcheck span,\nbody[data-contrast=\"high\"] .typehist button{\n  background:#151C26 !important;\n  color:var(--ink) !important;\n  border-color:rgba(255,255,255,.16) !important;\n  box-shadow:0 6px 22px rgba(0,0,0,.38) !important;\n  backdrop-filter:none !important;\n}\nbody[data-contrast=\"high\"] .hero-panel{\n  background:linear-gradient(145deg,#171F2B 0%,#121923 100%) !important;\n}\nbody[data-contrast=\"high\"] .scenario-item{box-shadow:none !important;background:#1B2431 !important}\nbody[data-contrast=\"high\"] .scenario-item.coming{opacity:.72}\nbody[data-contrast=\"high\"] .support-card .support-icon{background:#252E40;color:#F4F7FB}\nbody[data-contrast=\"high\"] .path.step-card.locked{opacity:.72;filter:saturate(.8)}\nbody[data-contrast=\"high\"] .progress-ring{background:conic-gradient(#8D6BFF calc(var(--pct)*1%),#30394A 0)}\nbody[data-contrast=\"high\"] .progress-ring::after{background:#151C26}\nbody[data-contrast=\"high\"] .progress-ring b{color:#F2ECFF}\nbody[data-contrast=\"high\"] .guide-bubble{background:#1B2431;color:#DDE5F0;border-color:rgba(255,255,255,.16);box-shadow:0 8px 24px rgba(0,0,0,.35)}\nbody[data-contrast=\"high\"] .guide-bubble strong{color:#E8DFFF}\n\n/* All typography and labels must inherit the dark palette */\nbody[data-contrast=\"high\"] .brand-name,\nbody[data-contrast=\"high\"] .hero-center h1,\nbody[data-contrast=\"high\"] .hero-center p,\nbody[data-contrast=\"high\"] .progress-card h3,\nbody[data-contrast=\"high\"] .progress-copy,\nbody[data-contrast=\"high\"] .progress-copy strong,\nbody[data-contrast=\"high\"] .modepick .mode,\nbody[data-contrast=\"high\"] .path .tx h3,\nbody[data-contrast=\"high\"] .path .tx p,\nbody[data-contrast=\"high\"] .path .st,\nbody[data-contrast=\"high\"] .support-card strong,\nbody[data-contrast=\"high\"] .support-card small,\nbody[data-contrast=\"high\"] .scenario-card h3,\nbody[data-contrast=\"high\"] .scenario-card>p,\nbody[data-contrast=\"high\"] .scenario-item b,\nbody[data-contrast=\"high\"] .scenario-item small,\nbody[data-contrast=\"high\"] .catcard .cn,\nbody[data-contrast=\"high\"] .catcard .cs,\nbody[data-contrast=\"high\"] .typebox-title h2,\nbody[data-contrast=\"high\"] .typebox-title p,\nbody[data-contrast=\"high\"] .topbar .title,\nbody[data-contrast=\"high\"] .topbar .stars,\nbody[data-contrast=\"high\"] .scene .say,\nbody[data-contrast=\"high\"] .scene .sub,\nbody[data-contrast=\"high\"] .stat .n,\nbody[data-contrast=\"high\"] .stat .l,\nbody[data-contrast=\"high\"] .legend span,\nbody[data-contrast=\"high\"] .bank-label,\nbody[data-contrast=\"high\"] .heard,\nbody[data-contrast=\"high\"] .phrase .pt,\nbody[data-contrast=\"high\"] .phrase .ps,\nbody[data-contrast=\"high\"] .setrow,\nbody[data-contrast=\"high\"] .soundrow,\nbody[data-contrast=\"high\"] .strip .hint{\n  color:var(--ink) !important;\n}\nbody[data-contrast=\"high\"] .hero-center p,\nbody[data-contrast=\"high\"] .path .tx p,\nbody[data-contrast=\"high\"] .support-card small,\nbody[data-contrast=\"high\"] .scenario-card>p,\nbody[data-contrast=\"high\"] .scenario-item small,\nbody[data-contrast=\"high\"] .catcard .cs,\nbody[data-contrast=\"high\"] .typebox-title p,\nbody[data-contrast=\"high\"] .scene .sub,\nbody[data-contrast=\"high\"] .stat .l,\nbody[data-contrast=\"high\"] .legend span,\nbody[data-contrast=\"high\"] .bank-label,\nbody[data-contrast=\"high\"] .heard,\nbody[data-contrast=\"high\"] .strip .hint{\n  color:var(--ink-soft) !important;\n}\n\n/* Header controls */\nbody[data-contrast=\"high\"] .access-btn,\nbody[data-contrast=\"high\"] .text-size-group{\n  background:#151C26 !important;\n  color:var(--ink) !important;\n  border-color:rgba(255,255,255,.16) !important;\n}\nbody[data-contrast=\"high\"] .access-btn small,\nbody[data-contrast=\"high\"] .text-size-group small{color:#C4CEDB !important}\nbody[data-contrast=\"high\"] .text-size-group button{\n  background:#232D3B !important;color:#FFFFFF !important;border-color:rgba(255,255,255,.18) !important;\n}\nbody[data-contrast=\"high\"] .access-btn[aria-pressed=\"true\"]{\n  background:#25203B !important;border-color:#8E77E8 !important;color:#FFFFFF !important;\n}\n\n/* The official icon always sits inside a visible light/colored bubble in dark mode. */\n.toolbar-voice-icon,.inline-voice-icon,.tab-voice-icon,.hero-voice-icon{object-fit:contain !important}\nbody[data-contrast=\"high\"] .hero-voice-icon{\n  background:linear-gradient(145deg,#F7F2FF,#DFF5FF) !important;\n  border:1px solid rgba(255,255,255,.82) !important;\n  padding:7px !important;\n  box-shadow:0 9px 24px rgba(0,0,0,.42),0 0 0 5px rgba(126,103,232,.10) !important;\n}\nbody[data-contrast=\"high\"] .toolbar-voice-icon,\nbody[data-contrast=\"high\"] .inline-voice-icon,\nbody[data-contrast=\"high\"] .tab-voice-icon{\n  background:linear-gradient(145deg,#F7F2FF,#DFF5FF) !important;\n  border:1px solid rgba(255,255,255,.75) !important;\n  padding:3px !important;\n  box-shadow:0 3px 9px rgba(0,0,0,.32) !important;\n}\nbody[data-contrast=\"high\"] .tab-voice-icon{width:28px;height:28px}\nbody[data-contrast=\"high\"] .voice-pill{\n  background:#222B3A !important;border-color:#7888A4 !important;color:#FFFFFF !important;\n  box-shadow:0 6px 18px rgba(0,0,0,.30);\n}\n\n/* Tabs: visible in both selected and unselected states */\nbody[data-contrast=\"high\"] .modepick .mode{color:#DCE5F2 !important}\nbody[data-contrast=\"high\"] .modepick .mode.active{\n  background:linear-gradient(92deg,#275F75,#514A86) !important;\n  color:#FFFFFF !important;\n  box-shadow:0 0 0 1px rgba(121,198,227,.38),0 0 18px rgba(90,160,220,.20) !important;\n}\n\n/* Back/Home controls and secondary screens */\nbody[data-contrast=\"high\"] .home-btn,\nbody[data-contrast=\"high\"] .topbar .home-btn{\n  background:#202A38 !important;\n  color:#FFFFFF !important;\n  border-color:rgba(255,255,255,.22) !important;\n  box-shadow:0 5px 16px rgba(0,0,0,.34) !important;\n}\nbody[data-contrast=\"high\"] .topbar{color:var(--ink)}\nbody[data-contrast=\"high\"] .btn.ghost{\n  background:#202A38 !important;color:#FFFFFF !important;border-color:rgba(255,255,255,.20) !important;\n}\nbody[data-contrast=\"high\"] .typerow input{\n  background:#101720 !important;color:#FFFFFF !important;border-color:rgba(255,255,255,.22) !important;\n}\nbody[data-contrast=\"high\"] .typerow input::placeholder{color:#AEB9C8 !important}\nbody[data-contrast=\"high\"] .typerow .showbtn{background:#202A38 !important;color:#FFFFFF !important;border-color:rgba(255,255,255,.20) !important}\nbody[data-contrast=\"high\"] .strip .ctl{background:#202A38 !important;color:#FFFFFF !important;border-color:rgba(255,255,255,.18) !important}\nbody[data-contrast=\"high\"] .strip-wrap{background:linear-gradient(to top,#0B1017 72%,transparent) !important}\nbody[data-contrast=\"high\"] .chips span{background:#202A38 !important;color:#FFFFFF !important;border-color:rgba(255,255,255,.18) !important}\nbody[data-contrast=\"high\"] .skilltag.t1{background:#1D3653 !important;color:#A9D3FF !important}\nbody[data-contrast=\"high\"] .skilltag.t2{background:#193A31 !important;color:#91E8C0 !important}\nbody[data-contrast=\"high\"] .skilltag.t3{background:#493123 !important;color:#FFC39A !important}\nbody[data-contrast=\"high\"] .skilltag.t4{background:#443B1E !important;color:#F5DA7A !important}\n\n/* My Words quick tiles retain semantic color while staying dark-mode legible. */\nbody[data-theme=\"aphasia\"][data-contrast=\"high\"] .quick:nth-child(1){background:#163227 !important;color:#9AF0C1 !important}\nbody[data-theme=\"aphasia\"][data-contrast=\"high\"] .quick:nth-child(2){background:#3A2020 !important;color:#FFB7AE !important}\nbody[data-theme=\"aphasia\"][data-contrast=\"high\"] .quick:nth-child(3){background:#14303A !important;color:#9BE2F3 !important}\nbody[data-theme=\"aphasia\"][data-contrast=\"high\"] .quick:nth-child(4){background:#3A3218 !important;color:#F7DA91 !important}\n\n\n\n/* ===== Semantic mode-tab icons =====\n   Consistent vector icons replace platform-dependent emoji in every mode. */\n.mode-tab-icon{\n  width:24px;height:24px;display:inline-grid;place-items:center;flex:0 0 24px;\n  line-height:0;transition:color .15s ease,transform .15s ease;\n}\n.mode-tab-icon svg{width:100%;height:100%;display:block;overflow:visible}\n.mode-tab-learning{color:#4F66C9}\n.mode-tab-english{color:#7652E5}\n.mode-tab-words{color:#13A85A}\n.modepick .mode.active .mode-tab-icon{color:#FFFFFF}\n.modepick .mode:active .mode-tab-icon{transform:scale(.94)}\nbody[data-contrast=\"high\"] .mode-tab-learning{color:#93AAFF}\nbody[data-contrast=\"high\"] .mode-tab-english{color:#C5B5FF}\nbody[data-contrast=\"high\"] .mode-tab-words{color:#5ADD91}\nbody[data-contrast=\"high\"] .modepick .mode.active .mode-tab-icon{color:#FFFFFF}\n@media (max-width:430px){\n  .mode-tab-icon{width:22px;height:22px;flex-basis:22px}\n}\n\n</style>\n<style id=\"eccoozs-host-link-style\">.ecc-host-link{position:fixed;right:12px;bottom:12px;z-index:99999;background:rgba(34,22,78,.92);color:#fff!important;text-decoration:none!important;padding:9px 13px;border-radius:999px;font:700 12px/1.2 Arial,sans-serif;box-shadow:0 8px 28px rgba(0,0,0,.22)}@media(max-width:560px){.ecc-host-link{font-size:11px;padding:8px 11px}}</style></head>\n<body>\n<div class=\"app\" id=\"app\"></div>\n<div class=\"strip-wrap\" id=\"stripWrap\" hidden>\n  <div class=\"strip\" role=\"group\" aria-label=\"My sentence\">\n    <div class=\"slot\" id=\"stripSlot\"><span class=\"hint\">Tap words to build what you want to say…</span></div>\n    <button class=\"ctl\" id=\"btnBack\" aria-label=\"Remove last word\" title=\"Remove last word\">⌫</button>\n    <button class=\"ctl\" id=\"btnClear\" aria-label=\"Clear sentence\" title=\"Clear\">🗑️</button>\n    <button class=\"ctl speak\" id=\"btnSpeak\" aria-label=\"Speak my sentence\">🔊 Say it</button>\n  </div>\n</div>\n\n<script>\n/* Hosted ECCOOZS build: use the browser/device speech voices instead of embedding 1,773 MP3 clips. */\nconst VOICE_BANKS={};\nlet AUDIO_BANK=undefined;\n</script>\n<script>\n/* =========================================================\n   My Voice Journey — an AAC learning game\n   Stages: 1 First Words → 2 Which Word? → 3 Build It → 4 Let's Talk\n   Plus a free Talk Board. Every tap speaks aloud.\n========================================================= */\n\n/* ---------- Speech ---------- */\n/* Plays bundled natural voice clips (AUDIO_BANK) when available; else device TTS.\n   say() accepts a string or an array of parts played in sequence. */\nconst Speech = {\n  rate: 0.95, pitch: 1.05, voice: null, useBank: false, voiceName:\"female\",\n  _seq:[], _cur:null,\n  init(){\n    if(!(\"speechSynthesis\" in window)) return;\n    const pick = () => {\n      const vs = speechSynthesis.getVoices();\n      const english=vs.filter(v=>/^en/i.test(v.lang));\n      const male=/male|david|mark|daniel|george|guy|ryan|alex|fred|thomas|aaron|arthur|james|john/i;\n      const female=/female|samantha|karen|zira|susan|victoria|ava|allison|aria|jenny|sara|emma/i;\n      const desired=this.voiceName===\"male\"?male:this.voiceName===\"female\"?female:null;\n      this.voice=(desired&&english.find(v=>desired.test(v.name))) || english[0] || vs[0] || null;\n    };\n    pick();\n    speechSynthesis.onvoiceschanged = pick;\n  },\n  stopAll(){\n    this._seq=[];\n    if(this._cur){ try{this._cur.pause();}catch(e){} this._cur=null; }\n    if(\"speechSynthesis\" in window) speechSynthesis.cancel();\n  },\n  say(parts, cb){\n    this.stopAll();\n    this._seq = (Array.isArray(parts)?parts:[parts]).filter(Boolean);\n    this._playNext(cb);\n  },\n  _playNext(cb){\n    const part = this._seq.shift();\n    if(part===undefined){ if(cb) cb(); return; }\n    const key = String(part).replace(/[^\\w\\s'!,.?:\\u2014-]/g,\"\").replace(/\\s+/g,\" \").trim();\n    if(this.useBank && typeof AUDIO_BANK!==\"undefined\" && AUDIO_BANK[key]){\n      const a = new Audio(\"data:audio/mpeg;base64,\"+AUDIO_BANK[key]);\n      a.playbackRate = this.rate/0.95;\n      this._cur = a;\n      a.onended = ()=>{ this._cur=null; this._playNext(cb); };\n      a.onerror = ()=>{ this._cur=null; this._tts(key, ()=>this._playNext(cb)); };\n      a.play().catch(()=>{ this._cur=null; this._tts(key, ()=>this._playNext(cb)); });\n    }else{\n      this._tts(key, ()=>this._playNext(cb));\n    }\n  },\n  _tts(text, done){\n    if(!(\"speechSynthesis\" in window)){ done(); return; }\n    const u = new SpeechSynthesisUtterance(text);\n    u.rate = this.rate; u.pitch = this.pitch;\n    if(this.voice) u.voice = this.voice;\n    u.onend = done; u.onerror = done;\n    speechSynthesis.speak(u);\n  }\n};\nSpeech.init();\n\n/* ---------- Listening (speech recognition) ---------- */\nconst Recog = {\n  supported: !!(window.SpeechRecognition || window.webkitSpeechRecognition),\n  active:null, timer:null,\n  listen(cbs){ // cbs: {onHear(alts[]), onSound(), onFail(err)}\n    const SR = window.SpeechRecognition || window.webkitSpeechRecognition;\n    if(!SR){ cbs.onFail(\"unsupported\"); return; }\n    if(\"speechSynthesis\" in window) speechSynthesis.cancel(); // don't hear ourselves\n    const r = new SR();\n    r.lang=\"en-US\"; r.interimResults=true; r.maxAlternatives=5; r.continuous=true;\n    let finals=[], interim=\"\", got=false, failed=null;\n    r.onaudiostart = ()=>{ if(cbs.onSound) cbs.onSound(); };\n    r.onresult = e=>{\n      for(let i=e.resultIndex;i<e.results.length;i++){\n        const res=e.results[i];\n        if(res.isFinal){ got=true; [...res].forEach(a=>a.transcript && finals.push(a.transcript.toLowerCase().trim())); }\n        else interim = (res[0].transcript||\"\").toLowerCase().trim();\n      }\n    };\n    r.onerror = e=>{ failed = e.error || \"error\"; };\n    r.onend = ()=>{\n      clearTimeout(Recog.timer);\n      if(got || interim){ cbs.onHear((finals.length?finals:[interim]).filter(Boolean)); }\n      else cbs.onFail(failed || \"no-speech\");\n    };\n    this.active=r;\n    try{ r.start(); }catch(err){ cbs.onFail(\"busy\"); return; }\n    // give slow speakers a generous 8-second window, then wrap up\n    this.timer = setTimeout(()=>{ try{ r.stop(); }catch(e){} }, 8000);\n  },\n  stop(){ clearTimeout(this.timer); try{ this.active && this.active.stop(); }catch(e){} }\n};\nconst MIC_BLOCKED = [\"not-allowed\",\"service-not-allowed\",\"audio-capture\",\"security\"];\n\n/* Forgiving matcher — developing speech deserves generous credit */\nfunction lev(a,b){\n  const m=[...Array(a.length+1)].map((_,i)=>[i,...Array(b.length)]);\n  for(let j=0;j<=b.length;j++) m[0][j]=j;\n  for(let i=1;i<=a.length;i++) for(let j=1;j<=b.length;j++)\n    m[i][j]=Math.min(m[i-1][j]+1, m[i][j-1]+1, m[i-1][j-1]+(a[i-1]===b[j-1]?0:1));\n  return m[a.length][b.length];\n}\nfunction normWords(s){ return s.toLowerCase().replace(/[^a-z\\s]/g,\"\").split(/\\s+/).filter(Boolean); }\nfunction wordHeard(target, tokens){\n  target = target.toLowerCase();\n  const tol = Math.max(1, Math.floor(target.length/3));\n  return tokens.some(t =>\n    t === target ||\n    (t.length >= 3 && (t.startsWith(target) || target.startsWith(t))) ||\n    lev(t, target) <= tol\n  );\n}\nfunction phraseScore(targetPhrase, transcripts){\n  // targetPhrase: \"I want juice please\" — check across all recognizer alternatives\n  const words = normWords(targetPhrase);\n  let best = {hits:[], score:0, heard:transcripts[0]||\"\"};\n  for(const tr of transcripts){\n    const tokens = normWords(tr);\n    const hits = words.map(w => wordHeard(w, tokens));\n    const score = hits.filter(Boolean).length / words.length;\n    if(score > best.score) best = {hits, score, heard:tr};\n  }\n  if(best.hits.length===0) best.hits = words.map(()=>false);\n  return {...best, words};\n}\n\n/* ---------- Per-sound coaching engine ---------- */\nconst SOUND_TIPS = {\n  b:\"Press your lips together, then pop them open: buh — buh!\",\n  p:\"Lips together, then a little puff of air: puh!\",\n  m:\"Close your lips and hum: mmm.\",\n  w:\"Make your lips round like blowing a bubble: wuh.\",\n  d:\"Tap your tongue behind your top teeth: duh.\",\n  t:\"Tongue taps up top with a tiny tick: tuh.\",\n  k:\"Make it in the back of your mouth, like a tiny cough: kuh.\",\n  c:\"Make it in the back of your mouth, like a tiny cough: kuh.\",\n  g:\"Back of your mouth, with your voice humming: guh.\",\n  s:\"Big smile, teeth close, make a snake sound: sss.\",\n  z:\"Big smile and buzz like a bee: zzz.\",\n  f:\"Top teeth touch your bottom lip and blow: fff.\",\n  v:\"Teeth on your lip with your voice on: vvv.\",\n  h:\"A soft puff of breath, like fogging a window: hhh.\",\n  j:\"Push your lips forward and jump the sound out: juh.\",\n  l:\"Tongue up to the bumpy spot behind your teeth and sing: lll.\",\n  n:\"Tongue up top and hum through your nose: nnn.\",\n  r:\"Curl your tongue back a little and growl softly: rrr.\",\n  y:\"Smile big and say: yuh.\",\n  th:\"Peek your tongue between your teeth and blow gently: th.\",\n  sh:\"Finger to your lips for the quiet sound: shhh.\",\n  ch:\"Make a tiny train sound: ch — ch!\",\n};\nconst DIGRAPHS = [\"th\",\"sh\",\"ch\"];\nfunction soundsOf(word){\n  word = String(word).toLowerCase().split(\" \")[0];\n  const out = [];\n  const onset = (word.match(/^[bcdfghjklmnpqrstvwxyz]+/)||[\"\"])[0];\n  if(onset){\n    if(DIGRAPHS.includes(onset.slice(0,2))) out.push(onset.slice(0,2));\n    else if(onset.length>=2) out.push(onset.slice(0,2)); // blend like dr, pl, st\n    else out.push(onset[0]);\n  }\n  DIGRAPHS.forEach(d=>{ if(word.includes(d) && !out.includes(d)) out.push(d); });\n  return out.length?out:[\"vowel\"];\n}\nfunction tipFor(s){\n  if(SOUND_TIPS[s]) return SOUND_TIPS[s];\n  if(s.length===2) return `Say it in two slow parts, then squeeze them together: ${s[0]}… ${s[1]}… ${s}!`;\n  return \"Watch a helper's mouth make the sound, then copy it slowly.\";\n}\nfunction recordWordAttempt(word, ok){\n  state.report.voiceTries++;\n  if(ok) state.report.voiceHits++;\n  const ws = state.report.wordStats[word] || (state.report.wordStats[word]={ok:0,miss:0});\n  ok ? ws.ok++ : ws.miss++;\n  soundsOf(word).forEach(s=>{\n    const rec = state.sounds[s] || (state.sounds[s]={ok:0,miss:0});\n    ok ? rec.ok++ : rec.miss++;\n  });\n}\nfunction trickySounds(){\n  return Object.entries(state.sounds)\n    .filter(([s,r])=>s!==\"vowel\" && r.miss>=2 && r.miss>r.ok)\n    .sort((a,b)=>b[1].miss-a[1].miss)\n    .map(([s])=>s);\n}\nfunction coachFor(word){\n  for(const s of soundsOf(word)){\n    const rec = state.sounds[s];\n    if(rec && rec.miss>=2 && rec.miss>rec.ok) return {sound:s, text:tipFor(s)};\n  }\n  return null;\n}\n\n/* ---------- \"Your turn to talk\" practice panel ---------- */\nfunction voicePractice(phrase, onDone){\n  if(!state.voiceOn || !Recog.supported || state.micBroken){ onDone(); return; }\n  let attempts = 0;\n  const words = normWords(phrase);\n  const ov = el(`<div class=\"overlay\"><div class=\"panel\" style=\"max-width:480px\">\n      <h2>🎤 Your turn to talk!</h2>\n      <div class=\"steps\">\n        <div class=\"step on\" id=\"vpS1\"><b>1</b> Listen</div>\n        <div class=\"step\" id=\"vpS2\"><b>2</b> Press the talk button</div>\n        <div class=\"step\" id=\"vpS3\"><b>3</b> Say it</div>\n      </div>\n      <div class=\"saytarget\">“${phrase}”</div>\n      <div class=\"wordcheck\" id=\"vpWords\">${words.map(w=>`<span>${w}</span>`).join(\"\")}</div>\n      <div class=\"heard\" id=\"vpHeard\">👂 Listen first…</div>\n      <button class=\"mic-btn\" id=\"vpMic\" disabled style=\"font-size:1.3rem;padding:18px 32px\">🎤 Press here, then say it</button>\n      <div style=\"display:flex;gap:10px;flex-wrap:wrap;justify-content:center\">\n        <button class=\"btn ghost\" id=\"vpHear\" style=\"font-size:1rem;padding:10px 20px\">🔊 Hear it again</button>\n        <button class=\"btn ghost\" id=\"vpSkip\" style=\"font-size:1rem;padding:10px 20px\">Skip →</button>\n      </div>\n    </div></div>`);\n  document.body.appendChild(ov);\n  const $ = s=>ov.querySelector(s);\n  const heardBox=$(\"#vpHeard\"), micBtn=$(\"#vpMic\");\n  const steps=[$(\"#vpS1\"),$(\"#vpS2\"),$(\"#vpS3\")];\n  const setStep=n=>steps.forEach((s,i)=>{s.classList.toggle(\"on\",i===n);s.classList.toggle(\"done\",i<n);});\n  const wordEls=[...ov.querySelectorAll(\"#vpWords span\")];\n  const close=()=>{ Recog.stop(); ov.remove(); onDone(); };\n  $(\"#vpSkip\").onclick = close;\n  $(\"#vpHear\").onclick = ()=>{ setStep(0); Speech.say([phrase], ()=>{ setStep(1); micBtn.disabled=false; }); };\n\n  // Step 1 happens automatically: model the phrase, then hand over\n  Speech.say([\"Your turn to talk! Listen:\", phrase], ()=>{\n    setStep(1);\n    micBtn.disabled = false;\n    heardBox.innerHTML = \"Now press the big talk button 👇\";\n    Speech.say([\"Now press the big talk button, and say:\", phrase]);\n  });\n\n  micBtn.onclick = ()=>{\n    micBtn.disabled = true;\n    setStep(2);\n    micBtn.classList.add(\"listening\");\n    micBtn.textContent = \"👂 SAY IT NOW: “\"+phrase+\"”\";\n    heardBox.textContent = \"I'm listening… speak nice and clear!\";\n    Recog.listen({\n      onSound: ()=>{ heardBox.textContent = \"✨ I can hear you…\"; },\n      onHear: alts=>{\n        micBtn.classList.remove(\"listening\");\n        micBtn.textContent = \"🎤 Press to try again\";\n        micBtn.disabled = false;\n        setStep(1);\n        attempts++;\n        const res = phraseScore(phrase, alts);\n        res.words.forEach((w,i)=>recordWordAttempt(w, !!res.hits[i]));\n        wordEls.forEach((elw,i)=>elw.classList.toggle(\"hit\", !!res.hits[i]));\n        heardBox.innerHTML = `I heard: <b>“${res.heard}”</b>`;\n        const said = res.words.filter((_,i)=>res.hits[i]);\n        const missed = res.words.filter((_,i)=>!res.hits[i]);\n        const coach = missed.length ? coachFor(missed[0]) : null;\n        if(res.score >= (words.length===1 ? 1 : 0.7)){\n          state.spokenWords += words.length;\n          heardBox.innerHTML += `<br>✅ <b>You said it with your own voice!</b>`;\n          Speech.say([\"You said it!\", phrase, \"Your voice is amazing!\"]);\n          setTimeout(close, 1900);\n        }else if(res.score > 0){\n          heardBox.innerHTML += `<br>💛 So close! I heard <b>${said.join(\", \")}</b>.`\n            + (coach ? `<br>🎯 <b>Sound tip for “${coach.sound}”:</b> ${coach.text}` : ` Press the button and try again.`);\n          Speech.say(coach\n            ? [\"So close! Here is a sound tip.\", coach.text, \"Press the button and try again:\", phrase]\n            : [\"So close! Press the button and try again:\", phrase]);\n          if(attempts>=3){ finishKind(); }\n        }else{\n          heardBox.innerHTML += `<br>💛 Good try!`\n            + (coach ? `<br>🎯 <b>Sound tip for “${coach.sound}”:</b> ${coach.text}` : ` Press the button and say “${phrase}” a little louder.`);\n          Speech.say(coach\n            ? [\"Good try! Here is a sound tip.\", coach.text, \"Press the button and try again:\", phrase]\n            : [\"Good try! Say it a little louder. Press the button and try again:\", phrase]);\n          if(attempts>=3){ finishKind(); }\n        }\n      },\n      onFail: err=>{\n        micBtn.classList.remove(\"listening\");\n        if(MIC_BLOCKED.includes(err)){ micProblem(ov, onDone); return; }\n        micBtn.textContent = \"🎤 Press here, then say it\";\n        micBtn.disabled = false;\n        setStep(1);\n        heardBox.innerHTML = \"🤔 I didn't catch a sound. Come a little closer, press the talk button, and say <b>“\"+phrase+\"”</b>.\";\n        Speech.say([\"I didn't hear you. Come closer, press the button, and say:\", phrase]);\n      }\n    });\n  };\n\n  function micProblem(ovEl, done){\n    state.micBroken = true;\n    ovEl.querySelector(\".panel\").innerHTML = `\n      <div class=\"big-em\">🎤🚫</div>\n      <h2>The microphone is blocked here</h2>\n      <p style=\"text-align:left\">This usually means one of two things:</p>\n      <p style=\"text-align:left;color:var(--ink-soft)\">\n        1️⃣ <b>You're in a preview window</b> (like inside a chat app). Download this file and open it\n        directly in <b>Chrome, Edge, or Safari</b> — then the mic will work.<br><br>\n        2️⃣ <b>The browser needs permission.</b> Look for the 🎤 icon near the address bar and choose <b>Allow</b>.\n      </p>\n      <p><b>No problem for now — we'll keep playing with buttons!</b></p>\n      <button class=\"btn\" id=\"vpOk\">OK, play with buttons 👍</button>`;\n    Speech.say(\"The microphone is blocked here, so we'll play with buttons for now!\");\n    ovEl.querySelector(\"#vpOk\").onclick = ()=>{ ovEl.remove(); done(); };\n  }\n\n  function finishKind(){\n    state.spokenWords += 1; // credit the effort\n    heardBox.innerHTML += `<br>🌟 <b>Wonderful practicing!</b> Every try makes your voice stronger.`;\n    Speech.say(\"Wonderful practicing! Every try makes your voice stronger.\");\n    setTimeout(close, 2200);\n  }\n}\n\n/* ---------- Vocabulary (Fitzgerald-style color coding) ---------- */\nconst W = {\n  // people (yellow)\n  I:{w:\"I\",e:\"🙋\",c:\"people\"}, you:{w:\"you\",e:\"🫵\",c:\"people\"}, mom:{w:\"mom\",e:\"👩\",c:\"people\"},\n  dad:{w:\"dad\",e:\"👨\",c:\"people\"}, friend:{w:\"friend\",e:\"🏃⚽🏃\",c:\"people\"}, me:{w:\"me\",e:\"🙋\",c:\"people\"},\n  we:{w:\"we\",e:\"👩👨\",c:\"people\"}, they:{w:\"they\",e:\"👤👤\",c:\"people\"}, us:{w:\"us\",e:\"🫶\",c:\"people\"},\n  your:{w:\"your\",e:\"👉\",c:\"people\"}, our:{w:\"our\",e:\"🤝\",c:\"people\"},\n  it:{w:\"it\",e:\"🔹\",c:\"people\"}, he:{w:\"he\",e:\"🙎‍♂️\",c:\"people\"}, she:{w:\"she\",e:\"🙎‍♀️\",c:\"people\"},\n  this:{w:\"this\",e:\"👇\",c:\"people\"}, that:{w:\"that\",e:\"☝️\",c:\"people\"}, there:{w:\"there\",e:\"👈\",c:\"people\"}, mine:{w:\"mine\",e:\"✊\",c:\"people\"},\n  come:{w:\"come\",e:\"🫴\",c:\"action\"}, look:{w:\"look\",e:\"🔍\",c:\"action\"}, get:{w:\"get\",e:\"🫳\",c:\"action\"},\n  put:{w:\"put\",e:\"📥\",c:\"action\"}, make:{w:\"make\",e:\"🔨\",c:\"action\"}, open:{w:\"open\",e:\"🔓\",c:\"action\"},\n  turn:{w:\"turn\",e:\"🔃\",c:\"action\"}, do:{w:\"do\",e:\"▶️\",c:\"action\"}, can:{w:\"can\",e:\"🆗\",c:\"action\"},\n  have:{w:\"have\",e:\"🧺\",c:\"action\"}, know:{w:\"know\",e:\"💡\",c:\"action\"}, say:{w:\"say\",e:\"💬\",c:\"action\"},\n  tell:{w:\"tell\",e:\"🗣️\",c:\"action\"}, give:{w:\"give\",e:\"🎁\",c:\"action\"}, take:{w:\"take\",e:\"🤏\",c:\"action\"},\n  work:{w:\"work\",e:\"💼\",c:\"action\"}, finish:{w:\"finish\",e:\"✔️\",c:\"action\"}, wait:{w:\"wait\",e:\"⏳\",c:\"action\"},\n  stay:{w:\"stay\",e:\"⚓\",c:\"action\"}, leave:{w:\"leave\",e:\"🚪\",c:\"action\"},\n  in:{w:\"in\",e:\"⤵️\",c:\"feeling\"}, out:{w:\"out\",e:\"⤴️\",c:\"feeling\"}, on:{w:\"on\",e:\"🔛\",c:\"feeling\"},\n  off:{w:\"off\",e:\"📴\",c:\"feeling\"}, up:{w:\"up\",e:\"⬆️\",c:\"feeling\"}, down:{w:\"down\",e:\"⬇️\",c:\"feeling\"},\n  again:{w:\"again\",e:\"🔁\",c:\"feeling\"}, now:{w:\"now\",e:\"⚡\",c:\"feeling\"}, later:{w:\"later\",e:\"🕔\",c:\"feeling\"},\n  all:{w:\"all\",e:\"💯\",c:\"feeling\"}, some:{w:\"some\",e:\"🍰\",c:\"feeling\"}, little:{w:\"little\",e:\"🐭\",c:\"feeling\"},\n  bad:{w:\"bad\",e:\"👎\",c:\"feeling\"}, same:{w:\"same\",e:\"🟰\",c:\"feeling\"}, different:{w:\"different\",e:\"🔀\",c:\"feeling\"},\n  fast:{w:\"fast\",e:\"🐇\",c:\"feeling\"}, slow:{w:\"slow\",e:\"🐢\",c:\"feeling\"},\n  red:{w:\"red\",e:\"🔴\",c:\"feeling\"}, orange:{w:\"orange\",e:\"🟠\",c:\"feeling\"}, yellow:{w:\"yellow\",e:\"🟡\",c:\"feeling\"},\n  green:{w:\"green\",e:\"🟢\",c:\"feeling\"}, blue:{w:\"blue\",e:\"🔵\",c:\"feeling\"}, purple:{w:\"purple\",e:\"🟣\",c:\"feeling\"},\n  pink:{w:\"pink\",e:\"🩷\",c:\"feeling\"}, brown:{w:\"brown\",e:\"🟤\",c:\"feeling\"}, black:{w:\"black\",e:\"⚫\",c:\"feeling\"},\n  white:{w:\"white\",e:\"⚪\",c:\"feeling\"},\n  not:{w:\"not\",e:\"🚫\",c:\"social\"}, dont:{w:\"don't\",e:\"⛔\",c:\"social\"},\n  what:{w:\"what\",e:\"❓\",c:\"social\"}, who:{w:\"who\",e:\"👤\",c:\"social\"}, when:{w:\"when\",e:\"🕐\",c:\"social\"},\n  why:{w:\"why\",e:\"🤔\",c:\"social\"}, how:{w:\"how\",e:\"🛠️\",c:\"social\"},\n  one:{w:\"one\",e:\"1️⃣\",c:\"social\"}, two:{w:\"two\",e:\"2️⃣\",c:\"social\"}, three:{w:\"three\",e:\"3️⃣\",c:\"social\"},\n  four:{w:\"four\",e:\"4️⃣\",c:\"social\"}, five:{w:\"five\",e:\"5️⃣\",c:\"social\"}, six:{w:\"six\",e:\"6️⃣\",c:\"social\"},\n  seven:{w:\"seven\",e:\"7️⃣\",c:\"social\"}, eight:{w:\"eight\",e:\"8️⃣\",c:\"social\"}, nine:{w:\"nine\",e:\"9️⃣\",c:\"social\"},\n  ten:{w:\"ten\",e:\"🔟\",c:\"social\"},\n  // actions (green)\n  want:{w:\"want\",e:\"🤲\",c:\"action\"}, eat:{w:\"eat\",e:\"🍽️\",c:\"action\"}, drink:{w:\"drink\",e:\"🥤\",c:\"action\"},\n  play:{w:\"play\",e:\"🪁\",c:\"action\"}, sleep:{w:\"sleep\",e:\"😴\",c:\"action\"}, go:{w:\"go\",e:\"🏃\",c:\"action\"},\n  stop:{w:\"stop\",e:\"✋\",c:\"action\"}, help:{w:\"help\",e:\"🆘\",c:\"action\"}, see:{w:\"see\",e:\"👀\",c:\"action\"},\n  read:{w:\"read\",e:\"📖\",c:\"action\"}, draw:{w:\"draw\",e:\"🖍️\",c:\"action\"}, feel:{w:\"feel\",e:\"💗\",c:\"action\"},\n  like:{w:\"like\",e:\"👍\",c:\"action\"}, hear:{w:\"hear\",e:\"👂\",c:\"action\"},\n  // feelings & describing (blue)\n  happy:{w:\"happy\",e:\"😊\",c:\"feeling\"}, sad:{w:\"sad\",e:\"😢\",c:\"feeling\"}, tired:{w:\"tired\",e:\"🥱\",c:\"feeling\"},\n  hungry:{w:\"hungry\",e:\"😋\",c:\"feeling\"}, thirsty:{w:\"thirsty\",e:\"💧\",c:\"feeling\"}, hurt:{w:\"hurt\",e:\"🤕\",c:\"feeling\"},\n  good:{w:\"good\",e:\"🌟\",c:\"feeling\"}, big:{w:\"big\",e:\"🐘\",c:\"feeling\"}, loud:{w:\"loud\",e:\"📢\",c:\"feeling\"},\n  hot:{w:\"hot\",e:\"🔥\",c:\"feeling\"}, cold:{w:\"cold\",e:\"🧊\",c:\"feeling\"}, silly:{w:\"silly\",e:\"🤪\",c:\"feeling\"},\n  // things (orange)\n  ball:{w:\"ball\",e:\"⚽\",c:\"thing\"}, juice:{w:\"juice\",e:\"🧃\",c:\"thing\"}, water:{w:\"water\",e:\"💦\",c:\"thing\"},\n  cookie:{w:\"cookie\",e:\"🍪\",c:\"thing\"}, book:{w:\"book\",e:\"📚\",c:\"thing\"}, dog:{w:\"dog\",e:\"🐶\",c:\"thing\"},\n  cat:{w:\"cat\",e:\"🐱\",c:\"thing\"}, music:{w:\"music\",e:\"🎵\",c:\"thing\"}, apple:{w:\"apple\",e:\"🍎\",c:\"thing\"},\n  outside:{w:\"outside\",e:\"🌳\",c:\"thing\"}, home:{w:\"home\",e:\"🏠\",c:\"thing\"}, blanket:{w:\"blanket\",e:\"🛏️\",c:\"thing\"},\n  // social (purple)\n  hello:{w:\"hello\",e:\"👋\",c:\"social\"}, goodbye:{w:\"goodbye\",e:\"🫱\",c:\"social\"}, please:{w:\"please\",e:\"🥺\",c:\"social\"},\n  thankyou:{w:\"thank you\",e:\"💐\",c:\"social\"}, yes:{w:\"yes\",e:\"✅\",c:\"social\"}, no:{w:\"no\",e:\"❌\",c:\"social\"},\n  more:{w:\"more\",e:\"➕\",c:\"social\"}, alldone:{w:\"all done\",e:\"🏁\",c:\"social\"}, my:{w:\"my\",e:\"💛\",c:\"people\"},\n  to:{w:\"to\",e:\"➡️\",c:\"social\"}, a:{w:\"a\",e:\"·\",c:\"social\"}, the:{w:\"the\",e:\"·\",c:\"social\"},\n};\nconst KIDS_CATS = {people:\"People\",action:\"Doing words\",feeling:\"Feelings\",thing:\"Things\",social:\"Little words\"};\n\n/* ---------- Stage data (KIDS) ---------- */\n// Stage 1: hear a word → find its picture (vocabulary + listening)\nconst KIDS_S1POOL = [\"eat\",\"drink\",\"play\",\"sleep\",\"help\",\"more\",\"stop\",\"happy\",\"sad\",\"ball\",\"juice\",\"book\",\"dog\",\"hello\",\"yes\",\"no\",\"hungry\",\"tired\",\"water\",\"cookie\"];\n\n// Stage 2: reasoning — a situation, pick the word that fits\nconst KIDS_S2 = [\n  {art:\"🍽️😣\", prompt:\"Your tummy is growling. What do you need to do?\", ans:\"eat\", opts:[\"eat\",\"sleep\",\"draw\"]},\n  {art:\"🥵💧\", prompt:\"You just ran and your mouth is dry. What do you need?\", ans:\"drink\", opts:[\"drink\",\"read\",\"stop\"]},\n  {art:\"🌙🥱\", prompt:\"It is nighttime and your eyes keep closing. What do you need to do?\", ans:\"sleep\", opts:[\"play\",\"sleep\",\"eat\"]},\n  {art:\"🎁😊\", prompt:\"Your friend gives you a present. What is the kind thing to say?\", ans:\"thankyou\", opts:[\"thankyou\",\"no\",\"stop\"]},\n  {art:\"🧗📦\", prompt:\"You can't reach your toy on the high shelf. What do you say?\", ans:\"help\", opts:[\"goodbye\",\"help\",\"sleep\"]},\n  {art:\"📢🙉\", prompt:\"The music hurts your ears. What do you want it to do?\", ans:\"stop\", opts:[\"more\",\"go\",\"stop\"]},\n  {art:\"🍪✨\", prompt:\"You finished your cookie and want another one. What do you say?\", ans:\"more\", opts:[\"more\",\"alldone\",\"no\"]},\n  {art:\"🥦😖\", prompt:\"Someone offers food you do not want. What do you say?\", ans:\"no\", opts:[\"yes\",\"no\",\"hello\"]},\n  {art:\"🚪👋\", prompt:\"A new friend walks in and waves at you. What do you say?\", ans:\"hello\", opts:[\"goodbye\",\"hello\",\"stop\"]},\n  {art:\"🤕🩹\", prompt:\"You fell and your knee hurts a lot. What do you say?\", ans:\"help\", opts:[\"play\",\"help\",\"more\"]},\n  {art:\"🍽️🏁\", prompt:\"Your plate is empty and your tummy is full. What do you say?\", ans:\"alldone\", opts:[\"more\",\"alldone\",\"hello\"]},\n  {art:\"🚌👋\", prompt:\"The bus is here and you are leaving school. What do you say?\", ans:\"goodbye\", opts:[\"hello\",\"goodbye\",\"help\"]},\n];\n\n// Stage 3: build a sentence to match a situation (order + logic, with distractors)\nconst KIDS_S3 = [\n  {art:\"⚽🙋\", prompt:\"Tell me you want the ball.\", target:[\"I\",\"want\",\"ball\"], extra:[\"sleep\",\"dog\"]},\n  {art:\"😊🙋\", prompt:\"Tell me how you feel when you are smiling.\", target:[\"I\",\"feel\",\"happy\"], extra:[\"sad\",\"ball\"]},\n  {art:\"🧃🥺\", prompt:\"Ask nicely for juice.\", target:[\"I\",\"want\",\"juice\",\"please\"], extra:[\"stop\",\"dog\"]},\n  {art:\"🐶👀\", prompt:\"Tell me what you see.\", target:[\"I\",\"see\",\"a\",\"dog\"], extra:[\"eat\",\"juice\"]},\n  {art:\"🆘🙋\", prompt:\"You need help. Ask for it nicely.\", target:[\"help\",\"me\",\"please\"], extra:[\"goodbye\",\"cookie\"]},\n  {art:\"🌳🏃\", prompt:\"Tell me where you want to go.\", target:[\"I\",\"want\",\"to\",\"go\",\"outside\"], extra:[\"sleep\",\"cat\"]},\n  {art:\"🎵👍\", prompt:\"Tell me that you like music.\", target:[\"I\",\"like\",\"music\"], extra:[\"no\",\"cold\"]},\n  {art:\"🥱🙋\", prompt:\"Tell me how you feel at bedtime.\", target:[\"I\",\"feel\",\"tired\"], extra:[\"big\",\"ball\"]},\n];\n\n// Stage 4: guided conversation — answer real questions with word tiles\nconst KIDS_S4 = [\n  {q:\"Hi there! I'm Leo. How do you feel today?\",\n   bank:[\"I\",\"feel\",\"happy\",\"sad\",\"tired\",\"silly\",\"hello\"],\n   need:[[\"I\",\"feel\",\"happy\"],[\"I\",\"feel\",\"sad\"],[\"I\",\"feel\",\"tired\"],[\"I\",\"feel\",\"silly\"]],\n   react:{happy:\"Yay! Happy days are the best! 😊\", sad:\"Aww, thank you for telling me. I'm here with you. 💙\",\n          tired:\"Sleepy friend! We can take it slow. 🥱\", silly:\"Hehe, I love silly! 🤪\"}},\n  {q:\"What do you want to do together?\",\n   bank:[\"I\",\"want\",\"to\",\"play\",\"read\",\"draw\",\"eat\",\"sleep\"],\n   need:[[\"I\",\"want\",\"to\",\"play\"],[\"I\",\"want\",\"to\",\"read\"],[\"I\",\"want\",\"to\",\"draw\"],[\"I\",\"want\",\"to\",\"eat\"]],\n   react:{play:\"Playing is my favorite! Let's do it! 🪁\", read:\"Books take us on adventures! 📚\",\n          draw:\"I'll get the crayons! 🖍️\", eat:\"Snack time! Yum! 🍪\"}},\n  {q:\"I'm thirsty! Do you want juice or water?\",\n   bank:[\"I\",\"want\",\"juice\",\"water\",\"please\",\"no\"],\n   need:[[\"I\",\"want\",\"juice\"],[\"I\",\"want\",\"water\"]],\n   react:{juice:\"Two juices coming up! 🧃\", water:\"Fresh cool water — great choice! 💦\"}},\n  {q:\"Here you go! What do we say when someone gives us something?\",\n   bank:[\"thankyou\",\"no\",\"stop\",\"more\",\"hello\"],\n   need:[[\"thankyou\"]],\n   react:{[\"thank you\"]:\"You're so welcome, friend! 💐\"}},\n  {q:\"This was so fun! It's time for me to go home. What do we say?\",\n   bank:[\"goodbye\",\"hello\",\"more\",\"yes\"],\n   need:[[\"goodbye\"]],\n   react:{goodbye:\"Goodbye, friend! You just had a whole conversation with me! 🎉\"}},\n];\n\n/* ---------- Adult / ESL content ---------- */\n// Extra vocabulary for grown-up, real-world English (merged into W at boot)\nconst ADULT_WORDS = {\n  // actions\n  need:{w:\"need\",e:\"🫴\",c:\"action\"}, would:{w:\"would\",e:\"💬\",c:\"action\"}, order:{w:\"order\",e:\"📋\",c:\"action\"},\n  pay:{w:\"pay\",e:\"💳\",c:\"action\"}, meet:{w:\"meet\",e:\"🤝\",c:\"action\"}, repeat:{w:\"repeat\",e:\"🔁\",c:\"action\"},\n  understand:{w:\"understand\",e:\"💡\",c:\"action\"}, find:{w:\"find\",e:\"🔎\",c:\"action\"}, buy:{w:\"buy\",e:\"🛍️\",c:\"action\"},\n  // feelings & states\n  fine:{w:\"fine\",e:\"🙂\",c:\"feeling\"}, sick:{w:\"sick\",e:\"🤒\",c:\"feeling\"}, ready:{w:\"ready\",e:\"👍\",c:\"feeling\"},\n  late:{w:\"late\",e:\"⏰\",c:\"feeling\"}, lost:{w:\"lost\",e:\"🧭\",c:\"feeling\"},\n  // things\n  coffee:{w:\"coffee\",e:\"☕\",c:\"thing\"}, tea:{w:\"tea\",e:\"🍵\",c:\"thing\"}, ticket:{w:\"ticket\",e:\"🎫\",c:\"thing\"},\n  doctor:{w:\"doctor\",e:\"🩺\",c:\"thing\"}, appointment:{w:\"appointment\",e:\"📅\",c:\"thing\"}, address:{w:\"address\",e:\"📍\",c:\"thing\"},\n  name:{w:\"name\",e:\"📛\",c:\"thing\"}, job:{w:\"job\",e:\"💼\",c:\"thing\"}, bill:{w:\"bill\",e:\"🧾\",c:\"thing\"},\n  menu:{w:\"menu\",e:\"📖\",c:\"thing\"}, bathroom:{w:\"bathroom\",e:\"🚻\",c:\"thing\"}, station:{w:\"station\",e:\"🚉\",c:\"thing\"},\n  // social & function words\n  sorry:{w:\"sorry\",e:\"🙏\",c:\"social\"}, okay:{w:\"okay\",e:\"👌\",c:\"social\"}, excuseme:{w:\"excuse me\",e:\"🙋\",c:\"social\"},\n  where:{w:\"where\",e:\"❓\",c:\"social\"}, is:{w:\"is\",e:\"·\",c:\"social\"}, am:{w:\"am\",e:\"·\",c:\"social\"},\n  are:{w:\"are\",e:\"·\",c:\"social\"},\n  here:{w:\"here\",e:\"📍\",c:\"social\"}, too:{w:\"too\",e:\"➕\",c:\"social\"}, like:{w:\"like\",e:\"👍\",c:\"action\"},\n};\n\nconst ADULT_S1POOL = [\"coffee\",\"water\",\"ticket\",\"doctor\",\"bathroom\",\"menu\",\"address\",\"name\",\"job\",\"bill\",\n  \"hello\",\"goodbye\",\"please\",\"thankyou\",\"yes\",\"no\",\"help\",\"sorry\",\"sick\",\"ready\"];\n\nconst ADULT_S2 = [\n  {art:\"☕🧑‍🍳\", prompt:\"The barista asks what you'd like to drink. You want a hot coffee. What do you say?\", ans:\"coffee\", opts:[\"coffee\",\"ticket\",\"doctor\"]},\n  {art:\"🍽️🚻\", prompt:\"You're at a restaurant and need the restroom. What do you ask for?\", ans:\"bathroom\", opts:[\"menu\",\"bathroom\",\"bill\"]},\n  {art:\"🍽️✅\", prompt:\"You've finished your meal and want to pay. What do you ask the waiter for?\", ans:\"bill\", opts:[\"bill\",\"menu\",\"water\"]},\n  {art:\"🤒🩺\", prompt:\"You feel unwell and want to be seen at a clinic. Who do you need?\", ans:\"doctor\", opts:[\"doctor\",\"job\",\"ticket\"]},\n  {art:\"🚉🎫\", prompt:\"You're at the station and need to travel. What do you buy first?\", ans:\"ticket\", opts:[\"menu\",\"ticket\",\"bill\"]},\n  {art:\"😅🗣️\", prompt:\"Someone spoke too fast and you didn't catch it. What do you ask them to do?\", ans:\"repeat\", opts:[\"repeat\",\"pay\",\"meet\"]},\n  {art:\"🙋💥\", prompt:\"You accidentally bump into a stranger on the street. What do you say?\", ans:\"sorry\", opts:[\"sorry\",\"hello\",\"yes\"]},\n  {art:\"🤝👔\", prompt:\"You arrive at a job interview and greet the manager. What do you say?\", ans:\"hello\", opts:[\"goodbye\",\"hello\",\"no\"]},\n  {art:\"📛✍️\", prompt:\"A form asks who you are. What information does it want?\", ans:\"name\", opts:[\"name\",\"job\",\"bill\"]},\n  {art:\"🎁🙏\", prompt:\"A coworker helps you finish a difficult task. What do you say?\", ans:\"thankyou\", opts:[\"thankyou\",\"sorry\",\"no\"]},\n  {art:\"🏠📍\", prompt:\"A delivery driver asks where you live. What do you give them?\", ans:\"address\", opts:[\"address\",\"menu\",\"ticket\"]},\n  {art:\"💼🔎\", prompt:\"You just moved to a new city and need work. What are you looking for?\", ans:\"job\", opts:[\"job\",\"coffee\",\"bill\"]},\n];\n\nconst ADULT_S3 = [\n  {art:\"☕🙋\", prompt:\"Order a coffee politely.\", target:[\"I\",\"would\",\"like\",\"a\",\"coffee\",\"please\"], extra:[\"ticket\",\"doctor\"]},\n  {art:\"🚻❓\", prompt:\"Ask where the bathroom is.\", target:[\"where\",\"is\",\"the\",\"bathroom\"], extra:[\"coffee\",\"ticket\"]},\n  {art:\"🩺📅\", prompt:\"Tell the receptionist you need to see a doctor.\", target:[\"I\",\"need\",\"to\",\"see\",\"a\",\"doctor\"], extra:[\"ticket\",\"menu\"]},\n  {art:\"😅🗣️\", prompt:\"Politely ask someone to repeat what they said.\", target:[\"please\",\"repeat\",\"that\"], extra:[\"coffee\",\"job\"]},\n  {art:\"🍽️👥\", prompt:\"Tell the waiter your group is ready to order.\", target:[\"we\",\"are\",\"ready\"], extra:[\"they\",\"coffee\"]},\n  {art:\"🧾💳\", prompt:\"Ask the waiter for the bill.\", target:[\"the\",\"bill\",\"please\"], extra:[\"menu\",\"doctor\"]},\n  {art:\"🚉🎫\", prompt:\"Ask to buy one ticket.\", target:[\"one\",\"ticket\",\"please\"], extra:[\"coffee\",\"doctor\"]},\n  {art:\"💼🔎\", prompt:\"Say that you are looking for a job.\", target:[\"I\",\"need\",\"a\",\"job\"], extra:[\"coffee\",\"menu\"]},\n];\n\nconst ADULT_S4 = [\n  {q:\"Hi, welcome in! How are you today?\",\n   bank:[\"I\",\"am\",\"fine\",\"good\",\"tired\",\"hello\"],\n   need:[[\"I\",\"am\",\"fine\"],[\"I\",\"am\",\"good\"],[\"I\",\"am\",\"tired\"]],\n   react:{fine:\"Glad to hear it! What can I get started for you? 🙂\", good:\"Wonderful! Let's get you sorted. 👍\",\n          tired:\"A warm drink might help with that! ☕\"}},\n  {q:\"Great. What would you like to drink?\",\n   bank:[\"I\",\"would\",\"like\",\"coffee\",\"tea\",\"water\",\"please\"],\n   need:[[\"I\",\"would\",\"like\",\"coffee\"],[\"I\",\"would\",\"like\",\"tea\"],[\"I\",\"would\",\"like\",\"water\"]],\n   react:{coffee:\"One coffee, coming right up! ☕\", tea:\"A lovely cup of tea it is! 🍵\", water:\"A fresh water for you! 💧\"}},\n  {q:\"Perfect. Would you like anything else?\",\n   bank:[\"no\",\"thankyou\",\"yes\",\"more\",\"water\"],\n   need:[[\"no\",\"thankyou\"],[\"yes\",\"water\"],[\"yes\",\"more\"]],\n   react:{[\"thank you\"]:\"No problem at all! 👌\", water:\"Sure, extra water coming up! 💧\", more:\"Of course, right away! ➕\"}},\n  {q:\"That comes to four dollars. Whenever you're ready.\",\n   bank:[\"here\",\"you\",\"are\",\"okay\",\"thankyou\"],\n   need:[[\"here\",\"you\",\"are\"],[\"okay\"]],\n   react:{here:\"Thank you very much! 💳\", okay:\"No rush at all! 👌\"}},\n  {q:\"All done! Thank you — have a great day!\",\n   bank:[\"thankyou\",\"you\",\"too\",\"goodbye\",\"hello\"],\n   need:[[\"thankyou\",\"you\",\"too\"],[\"goodbye\"]],\n   react:{[\"thank you\"]:\"You too! You just handled a whole real-life conversation in English! 🎉\",\n          goodbye:\"Goodbye! You just had a full English conversation! 🎉\"}},\n];\n\n\n/* Embedded official visual assets — keeps the app fully offline and single-file. */\nconst OFFICIAL_VOICE_ICON = '/learning-assets/my-voice-journey/voice-icon.png';\nconst LEO_WAVING_IMAGE = '/learning-assets/my-voice-journey/leo-waving.png';\nconst LEO_SEATED_IMAGE = '/learning-assets/my-voice-journey/leo-seated.png';\n\n/* ---------- Mode selection (kids ↔ adult/ESL) ---------- */\nlet S1_POOL, S2, S3, S4, CATS, PARTNER;\nfunction setMode(m, reset){\n  state.mode = m;\n  if(typeof document!==\"undefined\" && document.body) document.body.dataset.theme = m;\n  if(m===\"aphasia\"){\n    S1_POOL=ADULT_S1POOL; S2=ADULT_S2; S3=ADULT_S3; S4=ADULT_S4;\n    CATS={people:\"People\",action:\"Actions\",feeling:\"Feelings & states\",thing:\"Things\",social:\"Function words\"};\n    PARTNER={name:\"Sam\",face:\"🧑\"};\n  }else if(m===\"adult\"){\n    S1_POOL=ADULT_S1POOL; S2=ADULT_S2; S3=ADULT_S3; S4=ADULT_S4;\n    CATS={people:\"People\",action:\"Actions\",feeling:\"Feelings & states\",thing:\"Things\",social:\"Function words\"};\n    PARTNER={name:\"Sam\",face:\"🧑\"};\n  }else{\n    S1_POOL=KIDS_S1POOL; S2=KIDS_S2; S3=KIDS_S3; S4=KIDS_S4;\n    CATS=KIDS_CATS; PARTNER={name:\"Leo\",face:`<img class=\"partner-avatar\" src=\"${LEO_SEATED_IMAGE}\" alt=\"\">`};\n  }\n  if(reset){\n    state.stars={1:0,2:0,3:0,4:0}; state.unlocked=1;\n    state.spokenWords=0; state.sounds={};\n    state.report={ startedAt:Date.now(), voiceTries:0, voiceHits:0, wordStats:{}, gamesPlayed:{1:0,2:0,3:0,4:0} };\n  }\n}\n\n/* ---------- App state (in-memory) ---------- */\nObject.assign(W, ADULT_WORDS);      // both vocab sets share one tile dictionary\n\nconst state = {\n  screen:\"home\",\n  mode:\"kids\",                       // \"kids\" or \"adult\" (ESL / pronunciation)\n  stars:{1:0,2:0,3:0,4:0},          // 0–3 stars per stage\n  unlocked:1,\n  strip:[],                          // keys currently in the sentence strip\n  stage:null,                        // active stage runtime data\n  voiceOn:true,                      // practice speaking out loud after answers\n  textScale:1, contrast:false,       // display settings (persisted)\n  micBroken:false,                   // set true once the mic is found to be blocked\n  spokenWords:0,                     // words the learner has said with their own voice\n  sounds:{},                         // sound → {ok, miss} from voice attempts\n  report:{ startedAt:Date.now(), voiceTries:0, voiceHits:0, wordStats:{}, gamesPlayed:{1:0,2:0,3:0,4:0} },\n};\n\nconst app = document.getElementById(\"app\");\nconst stripWrap = document.getElementById(\"stripWrap\");\nconst stripSlot = document.getElementById(\"stripSlot\");\n\n/* ---------- Helpers ---------- */\nconst el = (html)=>{const d=document.createElement(\"div\");d.innerHTML=html.trim();return d.firstChild;};\nconst shuffle = a=>a.map(v=>[Math.random(),v]).sort((x,y)=>x[0]-y[0]).map(v=>v[1]);\nfunction toast(msg, kind){\n  document.querySelectorAll(\".toast\").forEach(t=>t.remove());\n  const t = el(`<div class=\"toast ${kind||\"\"}\">${msg}</div>`);\n  document.body.appendChild(t);\n  setTimeout(()=>t.remove(), 2200);\n}\nfunction starsStr(n){return \"⭐\".repeat(n)+\"☆\".repeat(3-n);}\nfunction tileHTML(key, cls){\n  const w=W[key];\n  return `<button class=\"tile cat-${w.c} ${cls||\"\"}\" data-key=\"${key}\" aria-label=\"${w.w}\">\n    <span class=\"em\">${w.e}</span><span class=\"lb\">${w.w}</span></button>`;\n}\n\n/* ---------- Sentence strip ---------- */\nfunction renderStrip(){\n  stripSlot.innerHTML = \"\";\n  if(state.strip.length===0){\n    stripSlot.innerHTML = `<span class=\"hint\">Tap words to build what you want to say…</span>`;\n    return;\n  }\n  state.strip.forEach(k=>{\n    const w=W[k];\n    stripSlot.appendChild(el(`<span class=\"chip cat-${w.c}\"><span class=\"em\">${w.e}</span>${w.w}</span>`));\n  });\n}\nfunction notifyStrip(){ if(state.onStripChange) state.onStripChange(); }\nfunction stripAdd(key){\n  if(state.strip.length>=8) return;\n  state.strip.push(key);\n  Speech.say(W[key].w);\n  renderStrip(); notifyStrip();\n}\nfunction stripText(){ return state.strip.map(k=>W[k].w).join(\" \"); }\ndocument.getElementById(\"btnBack\").onclick = ()=>{ state.strip.pop(); renderStrip(); notifyStrip(); };\ndocument.getElementById(\"btnClear\").onclick = ()=>{ state.strip=[]; renderStrip(); notifyStrip(); };\ndocument.getElementById(\"btnSpeak\").onclick = ()=>{\n  if(!state.strip.length){ Speech.say(\"Tap some words first!\"); return; }\n  Speech.say(state.strip.map(k=>W[k].w), ()=>{ if(state.onSpoken) state.onSpoken(); });\n};\n\n/* ---------- Screens ---------- */\nfunction go(screen){\n  state.screen=screen; state.strip=[]; state.onSpoken=null; state.onStripChange=null; renderStrip();\n  window.scrollTo(0,0);\n  ({home:renderHome, s1:renderS1, s2:renderS2, s3:renderS3, s4:renderS4, board:renderBoard, settings:renderSettings, gym:renderGym, report:renderReport, aphboard:renderAphBoard, customboard:renderCustomBoard})[screen]();\n}\n\nfunction topbar(title, stage){\n  return `<div class=\"topbar\">\n    <button class=\"home-btn\" onclick=\"go('home')\">🏠 Home</button>\n    <div class=\"title display\">${title}</div>\n    <div class=\"stars\">${stage?starsStr(state.stars[stage]):\"\"}</div>\n  </div>`;\n}\n\n\nfunction currentVoiceLabel(){\n  return Speech.voiceName===\"male\" ? \"Male\" : Speech.voiceName===\"female\" ? \"Female\" : \"Device\";\n}\nfunction adjustTextSize(delta){\n  state.textScale=Math.min(1.4,Math.max(.85,Math.round(((state.textScale||1)+delta)*100)/100));\n  applyDisplaySettings();persistSettings();\n}\nfunction toggleHighContrast(){\n  state.contrast=!state.contrast;applyDisplaySettings();persistSettings();\n  if(state.screen===\"home\") go(\"home\");\n}\nfunction mainHeader(){\n  return `<header class=\"main-header\" aria-label=\"App and accessibility controls\">\n    <button class=\"brand-home\" onclick=\"go('home')\" aria-label=\"My Voice Journey home\">\n      <span class=\"brand-mark\"><img src=\"${OFFICIAL_VOICE_ICON}\" alt=\"\"></span><span class=\"brand-name\">My Voice Journey</span>\n    </button>\n    <div class=\"accessbar\" aria-label=\"Accessibility\">\n      <button class=\"access-btn\" onclick=\"go('settings')\" aria-label=\"Voice settings, current voice ${currentVoiceLabel()}\"><span class=\"ai\"><img class=\"toolbar-voice-icon\" src=\"${OFFICIAL_VOICE_ICON}\" alt=\"\"></span><small>Voice</small></button>\n      <div class=\"text-size-group\" aria-label=\"Text size controls\">\n        <button onclick=\"adjustTextSize(-.1)\" aria-label=\"Decrease text size\">A−</button>\n        <span class=\"ts-label\"><b>Aa</b><small>Text size</small></span>\n        <button onclick=\"adjustTextSize(.1)\" aria-label=\"Increase text size\">A＋</button>\n      </div>\n      <button class=\"access-btn\" onclick=\"toggleHighContrast()\" aria-pressed=\"${state.contrast?'true':'false'}\" aria-label=\"${state.contrast?'Switch to light display':'Switch to high-contrast dark display'}\"><span class=\"ai\">◐</span><small>Contrast</small></button>\n      <button class=\"access-btn\" onclick=\"go('settings')\" aria-label=\"Open settings\"><span class=\"ai\">⚙️</span><small>Settings</small></button>\n    </div>\n  </header>`;\n}\nfunction mainModePicker(active){\n  const learningIcon = `<span class=\"mode-tab-icon mode-tab-learning\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\" focusable=\"false\"><path d=\"M3.5 5.4c2.9-.7 5.3-.1 7.5 1.5v12c-2.2-1.6-4.6-2.2-7.5-1.5zM20.5 5.4c-2.9-.7-5.3-.1-7.5 1.5v12c2.2-1.6 4.6-2.2 7.5-1.5z\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M12 6.9v12\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\"/></svg></span>`;\n  const englishIcon = `<span class=\"mode-tab-icon mode-tab-english\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\" focusable=\"false\"><path d=\"M3.2 10.2c0-3.6 3.4-6.3 7.7-6.3s7.7 2.7 7.7 6.3-3.4 6.3-7.7 6.3c-1 0-2-.1-2.8-.4l-3.7 2 .9-3.3c-1.3-1.1-2.1-2.7-2.1-4.6Z\" fill=\"currentColor\"/><path d=\"M14.2 17.1c3.6-.5 6.2-2.7 6.2-5.6 0-.8-.2-1.6-.6-2.3.7.9 1 2 1 3.2 0 1.6-.7 3-1.9 4l.7 2.8-3-1.6c-.8.2-1.6.3-2.4.3z\" fill=\"currentColor\" opacity=\".72\"/></svg></span>`;\n  const wordsIcon = `<span class=\"mode-tab-icon mode-tab-words\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\" focusable=\"false\"><circle cx=\"12\" cy=\"7\" r=\"4\" fill=\"currentColor\"/><path d=\"M4.3 20c.3-5 3-7.6 7.7-7.6s7.4 2.6 7.7 7.6z\" fill=\"currentColor\"/></svg></span>`;\n  return `<div class=\"modepick\" role=\"tablist\" aria-label=\"Choose a mode\">\n    <button class=\"mode ${active==='kids'?'active':''}\" onclick=\"switchMode('kids')\" role=\"tab\" aria-selected=\"${active==='kids'}\">${learningIcon}<span>Learning to Speak</span></button>\n    <button class=\"mode ${active==='adult'?'active':''}\" onclick=\"switchMode('adult')\" role=\"tab\" aria-selected=\"${active==='adult'}\">${englishIcon}<span>English Practice</span></button>\n    <button class=\"mode ${active==='aphasia'?'active':''}\" onclick=\"switchMode('aphasia')\" role=\"tab\" aria-selected=\"${active==='aphasia'}\">${wordsIcon}<span>My Words</span></button>\n  </div>`;\n}\nfunction progressSummary(){\n  const earned=Object.values(state.stars).reduce((a,b)=>a+b,0);\n  const pct=Math.round((earned/12)*100);\n  return {earned,pct};\n}\nwindow.adjustTextSize=adjustTextSize;\nwindow.toggleHighContrast=toggleHighContrast;\n\n\n/* ===== HOME ===== */\nfunction renderHome(){\n  stripWrap.hidden = true;\n  if(state.mode===\"aphasia\"){ renderAphasiaHome(); return; }\n  const adult = state.mode===\"adult\";\n  const TAGS={1:\"Builds listening\",2:\"Builds understanding\",3:\"Builds expression\",4:\"Builds confidence\"};\n  const p = (n,emoji,bg,name,desc)=>{\n    const locked = n>state.unlocked;\n    return `<button class=\"path step-card ${locked?\"locked\":\"\"}\" ${locked?\"disabled\":`onclick=\"go('s${n}')\"`}>\n      <div class=\"badge\" style=\"background:${bg}\">${emoji}</div>\n      <div class=\"tx\"><h3>Step ${n} · ${name}</h3><p>${desc}</p><span class=\"skilltag t${n}\">${TAGS[n]}</span></div>\n      <div class=\"st\">${locked?\"🔒 Locked\":starsStr(state.stars[n])}</div>\n    </button>`;\n  };\n  const steps = adult ? [\n    p(1,\"🔤\",\"#EEF3FF\",\"Key Words\",\"Hear a word, then find the right picture.\"),\n    p(2,\"🧠\",\"#EDF8F0\",\"Which Word?\",\"Choose the word that fits the situation.\"),\n    p(3,\"🧩\",\"#EAF3FF\",\"Build a Sentence\",\"Put words in order to make a natural sentence.\"),\n    p(4,\"💬\",\"#FFF5E5\",\"Real Conversation\",\"Practice a full café conversation with confidence.\"),\n  ].join(\"\") : [\n    p(1,\"🔊\",\"#F2ECFF\",\"Hear Words\",\"Listen to a word and find the matching picture.\"),\n    p(2,\"👆\",\"#ECF8E8\",\"Choose the Answer\",\"Hear a word or question and choose the correct answer.\"),\n    p(3,\"💬\",\"#EAF3FF\",\"Build a Sentence\",\"Put words together to make your own sentence.\"),\n    p(4,\"🗣️\",\"#FFF3DF\",\"Have a Conversation\",`Practice a real back-and-forth conversation with ${PARTNER.name}.`),\n  ].join(\"\");\n  const {pct}=progressSummary();\n  const heroLeft = adult ? \"\" : `<div class=\"journey-guide\" aria-label=\"Leo, the Learning to Speak guide\">\n      <div class=\"leo-hero-frame\"><img class=\"leo-hero-img\" src=\"${LEO_WAVING_IMAGE}\" alt=\"Leo the lion wearing a purple backpack and waving\"></div>\n      <div class=\"guide-bubble\"><strong>Hi, I’m Leo.</strong>I’m here to help you practice and grow.</div>\n    </div>`;\n  const progress = `<aside class=\"progress-card\" aria-label=\"Learning progress\">\n      <h3>Your progress</h3><div class=\"progress-row\"><div class=\"progress-ring\" style=\"--pct:${pct}\"><b>${pct}%</b></div>\n      <div class=\"progress-copy\"><strong>${pct?\"Keep going\":\"Ready when you are\"}</strong>${pct?\"Every step builds your voice.\":\"Begin with Step 1.\"}</div></div>\n    </aside>`;\n  const utilities = `<div class=\"support-grid\">\n      <button class=\"support-card\" onclick=\"go('board')\"><span class=\"support-icon\">🎛️</span><span><strong>Talk Board</strong><small>Build and speak your own message.</small></span></button>\n      <button class=\"support-card\" onclick=\"go('gym')\"><span class=\"support-icon\">🎯</span><span><strong>Sound Coach</strong><small>Practice sounds that feel difficult.</small></span></button>\n      <button class=\"support-card\" onclick=\"go('report')\"><span class=\"support-icon\">📊</span><span><strong>Progress Report</strong><small>${adult?\"For learners, teachers and tutors.\":\"For families, teachers and therapists.\"}</small></span></button>\n      <button class=\"support-card\" onclick=\"go('settings')\"><span class=\"support-icon\">⚙️</span><span><strong>Voice Settings</strong><small>Voice, speed, text size and contrast.</small></span></button>\n    </div>`;\n  const scenarios = adult ? `<aside class=\"scenario-card\"><h3>Practice real-world English</h3><p>Café is available now. More conversations are planned.</p><div class=\"scenario-list\">\n      <button class=\"scenario-item\" onclick=\"go('s4')\"><span class=\"si\">☕</span><span class=\"sx\"><b>Café</b><small>Order food and drinks</small></span><span>›</span></button>\n      <div class=\"scenario-item coming\"><span class=\"si\">🩺</span><span class=\"sx\"><b>Doctor</b><small>Coming next</small></span></div>\n      <div class=\"scenario-item coming\"><span class=\"si\">✈️</span><span class=\"sx\"><b>Travel</b><small>Coming next</small></span></div>\n      <div class=\"scenario-item coming\"><span class=\"si\">🛍️</span><span class=\"sx\"><b>Shopping</b><small>Coming next</small></span></div>\n    </div></aside>` : progress;\n  app.innerHTML = `<div class=\"home-shell ${adult?'adult-home':'kid-home'}\">\n    ${mainHeader()}\n    <section class=\"hero-panel\"><div class=\"hero-grid\">${heroLeft}<div class=\"hero-center\">\n      <div class=\"hero-symbol\"><img class=\"hero-voice-icon\" src=\"${OFFICIAL_VOICE_ICON}\" alt=\"Voice\"></div>\n      <h1>${adult?\"English Practice\":\"My Voice Journey\"}</h1>\n      <p>${adult?\"Practice real-world English with listening, speaking and conversation support.\":\"Learn words step by step until you can share a whole conversation.\"}</p>\n      <button class=\"voice-pill\" onclick=\"Speech.say('${adult?\"Hello. Let us practice English together.\":\"Hello, friend. Let us learn together.\"}')\"><img class=\"inline-voice-icon\" src=\"${OFFICIAL_VOICE_ICON}\" alt=\"\"> Voice: <b>${currentVoiceLabel()}</b> · tap to hear</button>\n    </div>${adult?progress:\"\"}</div></section>\n    ${mainModePicker(adult?'adult':'kids')}\n    <div class=\"home-layout\"><main><div class=\"steps-grid\">${steps}</div>${utilities}</main><div class=\"side-stack\">${scenarios}</div></div>\n    <div class=\"legend\"><span><i style=\"background:var(--people)\"></i>${CATS.people}</span><span><i style=\"background:var(--action)\"></i>${CATS.action}</span><span><i style=\"background:var(--feeling)\"></i>${CATS.feeling}</span><span><i style=\"background:var(--thing)\"></i>${CATS.thing}</span><span><i style=\"background:var(--social)\"></i>${CATS.social}</span></div>\n  </div>`;\n}\nfunction switchMode(m){\n  if(state.mode===m){ return; }\n  const hasProgress = state.spokenWords>0 || Object.values(state.stars).some(v=>v>0);\n  if(hasProgress && !confirm(\"Switch mode? This starts a fresh session (progress in the current mode will clear).\")){ return; }\n  setMode(m, true);\n  Speech.say(m===\"adult\" ? \"English practice mode.\" : m===\"aphasia\" ? \"My Words.\" : \"Learning to speak mode.\");\n  go(\"home\");\n}\n\n/* ===== Shared round machinery ===== */\nfunction finishStage(stage, correct, total){\n  state.report.gamesPlayed[stage]++;\n  const stars = correct>=total ? 3 : correct>=Math.ceil(total*0.7) ? 2 : correct>=Math.ceil(total*0.4) ? 1 : 0;\n  state.stars[stage] = Math.max(state.stars[stage], stars);\n  if(stars>=1 && state.unlocked===stage && stage<4) state.unlocked=stage+1;\n  const msgs = {\n    3:[\"Amazing!\",\"You got every single one! 🌟\"],\n    2:[\"Great job!\",\"So close to perfect — you're really getting it!\"],\n    1:[\"Nice work!\",\"You're learning! Play again to earn more stars.\"],\n    0:[\"Good try!\",\"Every try makes you stronger. Let's play again!\"],\n  }[stars];\n  Speech.say([msgs[0]+\" \"+msgs[1]]);\n  const overlay = el(`<div class=\"overlay\"><div class=\"panel\">\n      <div class=\"big-em bouncy\">${stars>=2?\"🎉\":\"💪\"}</div>\n      <h2>${msgs[0]} ${starsStr(stars)}</h2>\n      <p>${msgs[1]}</p>\n      ${stars>=1 && stage<4 ? `<p><b>Step ${stage+1} is unlocked!</b> 🔓</p>`:\"\"}\n      <div style=\"display:flex;gap:10px;flex-wrap:wrap;justify-content:center\">\n        <button class=\"btn ghost\" id=\"ovAgain\">Play again</button>\n        <button class=\"btn\" id=\"ovHome\">${stars>=1&&stage<4?\"Next step →\":\"Home\"}</button>\n      </div>\n    </div></div>`);\n  document.body.appendChild(overlay);\n  overlay.querySelector(\"#ovAgain\").onclick=()=>{overlay.remove();go(\"s\"+stage);};\n  overlay.querySelector(\"#ovHome\").onclick=()=>{overlay.remove(); (stars>=1&&stage<4)?go(\"s\"+(stage+1)):go(\"home\");};\n}\n\n/* ===== STAGE 1: First Words ===== */\nfunction renderS1(){\n  stripWrap.hidden = true;\n  const rounds = shuffle(S1_POOL).slice(0,8);\n  state.stage = {i:0, correct:0, rounds, tries:0};\n  drawS1();\n}\nfunction drawS1(){\n  const st=state.stage;\n  if(st.i>=st.rounds.length){ finishStage(1, st.correct, st.rounds.length); return; }\n  const answer = st.rounds[st.i];\n  const opts = shuffle([answer, ...shuffle(S1_POOL.filter(k=>k!==answer)).slice(0,3)]);\n  st.tries=0;\n  app.innerHTML = topbar(\"First Words\",1) + `\n    <div class=\"progressdots\">${st.rounds.map((_,j)=>`<i class=\"${j<st.i?\"on\":\"\"}\"></i>`).join(\"\")}</div>\n    <div class=\"card scene\">\n      <div class=\"say\">Listen… then find the picture!</div>\n      <button class=\"listen\" id=\"hear\">🔊 Hear the word</button>\n      <div class=\"sub\">Tap the speaker any time to hear it again.</div>\n    </div>\n    <div class=\"tilegrid\" style=\"grid-template-columns:repeat(2,1fr)\">\n      ${opts.map(k=>tileHTML(k,\"big\")).join(\"\")}\n    </div>`;\n  const hear=()=>Speech.say([\"Find:\", W[answer].w]);\n  document.getElementById(\"hear\").onclick=hear;\n  setTimeout(hear, 350);\n  app.querySelectorAll(\".tile\").forEach(t=>t.onclick=()=>{\n    const k=t.dataset.key;\n    if(k===answer){\n      Speech.say([W[answer].w, \"Yes!\"]);\n      t.classList.add(\"bouncy\");\n      if(st.tries===0) st.correct++;\n      toast(`${W[answer].e} ${W[answer].w} — that's it!`,\"good\");\n      setTimeout(()=>voicePractice(W[answer].w, ()=>{st.i++;drawS1();}), 1100);\n    }else{\n      st.tries++;\n      Speech.say([\"That one says:\", W[k].w, \"Listen again!\"]);\n      toast(`That's \"${W[k].w}\". Try again! 👂`,\"try\");\n      t.classList.add(\"dim\");\n    }\n  });\n}\n\n/* ===== STAGE 2: Which Word? (reasoning) ===== */\nfunction renderS2(){\n  stripWrap.hidden = true;\n  state.stage = {i:0, correct:0, rounds: shuffle(S2).slice(0,8), tries:0};\n  drawS2();\n}\nfunction drawS2(){\n  const st=state.stage;\n  if(st.i>=st.rounds.length){ finishStage(2, st.correct, st.rounds.length); return; }\n  const r = st.rounds[st.i];\n  st.tries=0;\n  app.innerHTML = topbar(\"Which Word?\",2) + `\n    <div class=\"progressdots\">${st.rounds.map((_,j)=>`<i class=\"${j<st.i?\"on\":\"\"}\"></i>`).join(\"\")}</div>\n    <div class=\"card scene\">\n      <div class=\"art\">${r.art}</div>\n      <div class=\"say\">${r.prompt}</div>\n      <button class=\"listen\" id=\"hear\">🔊 Read it to me</button>\n    </div>\n    <div class=\"tilegrid\" style=\"grid-template-columns:repeat(3,1fr)\">\n      ${shuffle(r.opts).map(k=>tileHTML(k,\"big\")).join(\"\")}\n    </div>`;\n  const hear=()=>Speech.say(r.prompt);\n  document.getElementById(\"hear\").onclick=hear;\n  setTimeout(hear,350);\n  app.querySelectorAll(\".tile\").forEach(t=>t.onclick=()=>{\n    const k=t.dataset.key;\n    Speech.say(W[k].w);\n    if(k===r.ans){\n      if(st.tries===0) st.correct++;\n      t.classList.add(\"bouncy\");\n      setTimeout(()=>Speech.say([\"Yes!\", W[k].w, \"is just right.\"]), 500);\n      toast(`✅ \"${W[k].w}\" fits perfectly!`,\"good\");\n      setTimeout(()=>voicePractice(W[r.ans].w, ()=>{st.i++;drawS2();}), 1400);\n    }else{\n      st.tries++;\n      toast(`Hmm — would \"${W[k].w}\" fix that? Think again 🧠`,\"try\");\n      setTimeout(()=>Speech.say([\"Hmm, would\", W[k].w, \"fix that? Think again.\"]), 500);\n      t.classList.add(\"dim\");\n    }\n  });\n}\n\n/* ===== STAGE 3: Build It ===== */\nfunction renderS3(){\n  stripWrap.hidden = false;\n  state.stage = {i:0, correct:0, rounds: shuffle(S3).slice(0,6), tries:0};\n  drawS3();\n}\nfunction drawS3(){\n  const st=state.stage;\n  state.strip=[]; renderStrip();\n  if(st.i>=st.rounds.length){ stripWrap.hidden=true; state.onStripChange=null; finishStage(3, st.correct, st.rounds.length); return; }\n  const r = st.rounds[st.i];\n  st.tries=0;\n  app.innerHTML = topbar(\"Build It\",3) + `\n    <div class=\"progressdots\">${st.rounds.map((_,j)=>`<i class=\"${j<st.i?\"on\":\"\"}\"></i>`).join(\"\")}</div>\n    <div class=\"card scene\">\n      <div class=\"art\">${r.art}</div>\n      <div class=\"say\">${r.prompt}</div>\n      <div class=\"slots\" id=\"slots\"></div>\n      <div class=\"sub\">The sentence needs <b>${r.target.length} words</b>. Tap them in order, then press <b>🔊 Say it</b>.</div>\n      <button class=\"listen\" id=\"hear\">🔊 Read it to me</button>\n    </div>\n    <div class=\"bank-label\">Words for this sentence</div>\n    <div class=\"tilegrid\" id=\"needGrid\">${r.target.map(k=>tileHTML(k)).join(\"\")}</div>\n    <div class=\"bank-label\">Extra words — not needed this time</div>\n    <div class=\"tilegrid\" style=\"opacity:.85\" id=\"extraGrid\">${r.extra.map(k=>tileHTML(k)).join(\"\")}</div>`;\n  const hear=()=>Speech.say(r.prompt);\n  document.getElementById(\"hear\").onclick=hear;\n  setTimeout(hear,350);\n  app.querySelectorAll(\".tile\").forEach(t=>t.onclick=()=>stripAdd(t.dataset.key));\n  const drawSlots = ()=>{\n    const box=document.getElementById(\"slots\"); if(!box) return;\n    box.innerHTML = r.target.map((k,j)=>{\n      if(j<state.strip.length){\n        const w=W[state.strip[j]];\n        return `<span class=\"sl filled chip cat-${w.c}\" style=\"border-radius:14px\">${w.e} ${w.w}</span>`;\n      }\n      return `<span class=\"sl ${j===state.strip.length?\"next\":\"\"}\">${j===state.strip.length?\"next word\":\"&nbsp;\"}</span>`;\n    }).join(\"\");\n    // dim tiles already used so it's clear each word is placed once\n    app.querySelectorAll(\".tile\").forEach(t=>{\n      t.classList.toggle(\"dim\", state.strip.includes(t.dataset.key));\n    });\n  };\n  state.onStripChange = drawSlots;\n  drawSlots();\n  state.onSpoken = ()=>{\n    const got = state.strip.map(k=>W[k].w).join(\"|\");\n    const wantExact = r.target.map(k=>W[k].w).join(\"|\");\n    // also accept the sentence without small filler words if the target had them\n    const core = r.target.filter(k=>![\"a\",\"the\",\"to\"].includes(k)).map(k=>W[k].w).join(\"|\");\n    const gotCore = state.strip.filter(k=>![\"a\",\"the\",\"to\"].includes(k)).map(k=>W[k].w).join(\"|\");\n    if(got===wantExact || gotCore===core){\n      if(st.tries===0) st.correct++;\n      toast(\"🎉 You said a whole sentence!\",\"good\");\n      Speech.say(\"You built a whole sentence! Now let's hear your voice say it!\");\n      const sentence = r.target.map(k=>W[k].w).join(\" \");\n      setTimeout(()=>voicePractice(sentence, ()=>{st.i++;drawS3();}), 1600);\n    }else{\n      st.tries++;\n      const hint = W[r.target[Math.min(state.strip.length, r.target.length-1)] ]?.w;\n      toast(`Almost! Try starting with \"${W[r.target[0]].w}\" 💡`,\"try\");\n      Speech.say([\"Almost! Clear it and try again. Hint: one of the words is:\", hint]);\n    }\n  };\n}\n\n/* ===== STAGE 4: Let's Talk ===== */\nfunction renderS4(){\n  stripWrap.hidden = false;\n  state.stage = {i:0, correct:0, log:[], tries:0};\n  drawS4();\n}\nfunction drawS4(){\n  const st=state.stage;\n  state.strip=[]; renderStrip();\n  if(st.i>=S4.length){ stripWrap.hidden=true; finishStage(4, st.correct, S4.length); return; }\n  const turn = S4[st.i];\n  st.tries=0;\n  app.innerHTML = topbar(\"Let's Talk\",4) + `\n    <div class=\"progressdots\">${S4.map((_,j)=>`<i class=\"${j<st.i?\"on\":\"\"}\"></i>`).join(\"\")}</div>\n    <div class=\"card\">\n      <div class=\"chatlog\" id=\"log\">\n        ${st.log.map(m=>m.who===\"p\"\n          ? `<div class=\"partner-row\"><div class=\"face\">${PARTNER.face}</div><div class=\"bubble partner\">${m.t}</div></div>`\n          : `<div class=\"bubble me\">${m.t}</div>`).join(\"\")}\n        <div class=\"partner-row\"><div class=\"face\">${PARTNER.face}</div><div class=\"bubble partner\">${turn.q}</div></div>\n      </div>\n      <div style=\"text-align:center;margin-top:10px\">\n        <button class=\"listen\" id=\"hear\">🔊 Hear ${PARTNER.name} again</button>\n      </div>\n    </div>\n    <div class=\"card\" style=\"padding:12px\">\n      <div class=\"sub\" style=\"color:var(--ink-soft);text-align:center;margin-bottom:8px\">Build your answer, then press 🔊 Say it</div>\n      <div class=\"tilegrid\">${shuffle(turn.bank).map(k=>tileHTML(k)).join(\"\")}</div>\n      ${state.voiceOn && Recog.supported ? `\n      <div style=\"text-align:center;margin-top:12px\">\n        <button class=\"mic-inline\" id=\"micAns\">🎤 Or answer with my voice</button>\n      </div>`:\"\"}\n    </div>`;\n  const hear=()=>Speech.say([PARTNER.name+\" says:\", turn.q]);\n  document.getElementById(\"hear\").onclick=hear;\n  setTimeout(hear,400);\n  const logBox=document.getElementById(\"log\"); logBox.scrollTop=logBox.scrollHeight;\n  app.querySelectorAll(\".tile\").forEach(t=>t.onclick=()=>stripAdd(t.dataset.key));\n  const succeed = (match, displayText, spoke)=>{\n    if(st.tries===0) st.correct++;\n    if(spoke) state.spokenWords += normWords(displayText).length;\n    const keyword = match.map(k=>W[k].w).find(w=>turn.react[w]) || Object.keys(turn.react)[0];\n    const reply = turn.react[keyword] || \"That's wonderful!\";\n    st.log.push({who:\"p\",t:turn.q},{who:\"me\",t:(spoke?\"🎤 \":\"🗣️ \")+displayText});\n    Speech.say([spoke?\"Wow, your own voice!\":null, PARTNER.name+\" says:\", reply.replace(/[^\\w\\s'!,.?]/g,\"\").trim()]);\n    st.log.push({who:\"p\",t:reply});\n    setTimeout(()=>{st.i++;drawS4();}, spoke?2300:1900);\n  };\n  const micBtn = document.getElementById(\"micAns\");\n  if(micBtn && state.micBroken) micBtn.style.display=\"none\";\n  if(micBtn) micBtn.onclick = ()=>{\n    micBtn.classList.add(\"listening\"); micBtn.textContent=\"👂 Say your answer to \"+PARTNER.name+\" now!\";\n    Recog.listen({\n      onSound: ()=>{ micBtn.textContent=\"✨ I can hear you…\"; },\n      onHear: alts=>{\n        micBtn.classList.remove(\"listening\"); micBtn.textContent=\"🎤 Or answer with my voice\";\n        let best=null;\n        for(const seq of turn.need){\n          const phrase = seq.map(k=>W[k].w).join(\" \");\n          const res = phraseScore(phrase, alts);\n          if(!best || res.score>best.res.score) best={seq,res};\n        }\n        if(best && best.res.score>=0.7){\n          best.res.words.forEach((w,i)=>recordWordAttempt(w, !!best.res.hits[i]));\n          succeed(best.seq, best.res.heard, true);\n        }else{\n          st.tries++;\n          if(best) best.res.words.forEach((w,i)=>recordWordAttempt(w, !!best.res.hits[i]));\n          const heard = (best && best.res.heard) ? `I heard “${best.res.heard}”. ` : \"\";\n          toast(`👂 ${heard}${PARTNER.name} isn't sure — press the mic and try again, or use your buttons!`,\"try\");\n          Speech.say(\"Good talking! Press the microphone and try once more, or use your buttons.\");\n        }\n      },\n      onFail: err=>{\n        micBtn.classList.remove(\"listening\"); micBtn.textContent=\"🎤 Or answer with my voice\";\n        if(MIC_BLOCKED.includes(err)){\n          state.micBroken = true; micBtn.style.display=\"none\";\n          toast(\"🎤 The microphone is blocked here — buttons still work great!\",\"try\");\n        }else{\n          toast(\"I didn't hear anything — press the mic and speak right away!\",\"try\");\n        }\n      }\n    });\n  };\n  state.onSpoken = ()=>{\n    const saidKeys = state.strip.slice();\n    const saidWords = saidKeys.map(k=>W[k].w);\n    const match = turn.need.find(seq=>{\n      const want = seq.map(k=>W[k].w);\n      return want.every(w=>saidWords.includes(w)) && saidWords.length<=want.length+1;\n    });\n    if(match){\n      succeed(match, stripText(), false);\n    }else{\n      st.tries++;\n      toast(PARTNER.name+\" isn't sure that answers the question 🤔\",\"try\");\n      Speech.say(\"Hmm, does that answer my question? Look at the words and try again!\");\n    }\n  };\n}\n\n/* ===== FREE TALK BOARD ===== */\nfunction renderBoard(){\n  stripWrap.hidden = false;\n  state.strip=[]; renderStrip();\n  const order = [\"people\",\"action\",\"feeling\",\"thing\",\"social\"];\n  const groups = order.map(c=>{\n    const adultOnly = Object.keys(ADULT_WORDS);\n    const keys = Object.keys(W).filter(k=>W[k].c===c && ![\"a\",\"the\",\"to\"].includes(k)\n      && (state.mode!==\"kids\" || !adultOnly.includes(k)));\n    return `<h3 class=\"display\" style=\"margin:14px 4px 8px\">${CATS[c]}</h3>\n      <div class=\"tilegrid\">${keys.map(k=>tileHTML(k)).join(\"\")}</div>`;\n  }).join(\"\");\n  app.innerHTML = topbar(\"My Talk Board\") + `\n    <div class=\"card\" style=\"text-align:center;padding:14px\">\n      <b>This board is all yours.</b><br>\n      <span style=\"color:var(--ink-soft)\">Tap words to build anything you want to say, then press 🔊 Say it.</span>\n    </div>` + typeboxHTML() + groups + `<div style=\"height:8px\"></div>`;\n  app.querySelectorAll(\".tile\").forEach(t=>t.onclick=()=>stripAdd(t.dataset.key));\n  wireTypebox();\n  state.onSpoken = ()=>toast(\"🔊 You said it!\",\"good\");\n}\n\n/* ===== SETTINGS ===== */\nfunction renderSettings(){\n  stripWrap.hidden = true;\n  app.innerHTML = topbar(\"Voice & Accessibility\") + `\n    <div class=\"card\">\n      <div class=\"setrow\">\n        <div><b>Talking practice (microphone)</b><br><span style=\"color:var(--ink-soft);font-size:.9rem\">After right answers, the app listens for the learner's own voice.</span></div>\n        <button class=\"btn ghost\" id=\"voiceTog\">${state.voiceOn?\"On ✅\":\"Off ⭕\"}</button>\n      </div>\n      ${!Recog.supported?`<div class=\"setrow\"><div style=\"color:var(--ink-soft);font-size:.9rem\">⚠️ This browser can't listen to speech. For talking practice, open the app in <b>Chrome, Edge, or Safari</b>.</div></div>`:\"\"}\n      <div class=\"setrow\">\n        <div><b>Voice</b><br><span style=\"color:var(--ink-soft);font-size:.9rem\">Choose a female, male, or default device English voice when available on your phone or computer.</span></div>\n        <button class=\"btn ghost\" id=\"voicePick\">${Speech.voiceName===\"male\"?\"Male 🧔\":Speech.voiceName===\"female\"?\"Female 🌼\":\"Device 🖥️\"}</button>\n      </div>\n      <div class=\"setrow\">\n        <div><b>Talking speed</b><br><span style=\"color:var(--ink-soft);font-size:.9rem\">Slower can be easier to learn.</span></div>\n        <input type=\"range\" min=\"0.5\" max=\"1.3\" step=\"0.05\" value=\"${Speech.rate}\" id=\"rate\">\n      </div>\n      <div class=\"setrow\">\n        <div><b>Text size</b><br><span style=\"color:var(--ink-soft);font-size:.9rem\">Bigger text everywhere in the app.</span></div>\n        <div style=\"display:flex;gap:8px;align-items:center\">\n          <button class=\"btn ghost\" id=\"szDown\" style=\"padding:8px 16px\">A−</button>\n          <b id=\"szLabel\">${Math.round((state.textScale||1)*100)}%</b>\n          <button class=\"btn ghost\" id=\"szUp\" style=\"padding:8px 16px\">A＋</button>\n        </div>\n      </div>\n      <div class=\"setrow\">\n        <div><b>Light / dark contrast</b><br><span style=\"color:var(--ink-soft);font-size:.9rem\">Switch between the light view and a high-contrast dark view.</span></div>\n        <button class=\"btn ghost\" id=\"contrastTog\">${state.contrast?\"Dark 🌙\":\"Light ☀️\"}</button>\n      </div>\n      <div class=\"setrow\">\n        <div><b>Try the voice</b></div>\n        <button class=\"btn ghost\" id=\"test\">🔊 Hello, friend!</button>\n      </div>\n      <div class=\"setrow\">\n        <div><b>Test the microphone</b><br><span style=\"color:var(--ink-soft);font-size:.9rem\" id=\"micRes\">Press, say anything, and see if the app hears you.</span></div>\n        <button class=\"btn ghost\" id=\"micTest\">🎤 Test</button>\n      </div>\n    </div>\n    <div class=\"card\" style=\"color:var(--ink-soft);font-size:.95rem\">\n      💡 <b>For helpers:</b> talking practice is always optional and skippable — the learner is never blocked\n      for not vocalizing. The listener is generous on purpose: close attempts count, and after three tries the\n      app celebrates the effort and moves on. Colors follow a common AAC pattern — yellow for people, green for\n      doing words, blue for feelings, orange for things, purple for little social words.\n    </div>`;\n  document.getElementById(\"voiceTog\").onclick = e=>{\n    state.voiceOn = !state.voiceOn;\n    e.target.textContent = state.voiceOn?\"On ✅\":\"Off ⭕\";\n    Speech.say(state.voiceOn?\"Talking practice is on!\":\"Talking practice is off.\");\n  };\n  document.getElementById(\"rate\").oninput = e=>{Speech.rate=parseFloat(e.target.value); persistSettings();};\n  const szl=document.getElementById(\"szLabel\");\n  document.getElementById(\"szDown\").onclick=()=>{state.textScale=Math.max(.85,(state.textScale||1)-0.1); applyDisplaySettings(); persistSettings(); szl.textContent=Math.round(state.textScale*100)+\"%\";};\n  document.getElementById(\"szUp\").onclick=()=>{state.textScale=Math.min(1.4,(state.textScale||1)+0.1); applyDisplaySettings(); persistSettings(); szl.textContent=Math.round(state.textScale*100)+\"%\";};\n  document.getElementById(\"contrastTog\").onclick=e=>{state.contrast=!state.contrast; applyDisplaySettings(); persistSettings(); e.target.textContent=state.contrast?\"Dark 🌙\":\"Light ☀️\";};\n  document.getElementById(\"voicePick\").onclick = e=>{\n    const order=[\"female\",\"male\",\"device\"];\n    const cur=Speech.voiceName||\"device\";\n    const next=order[(order.indexOf(cur)+1)%order.length];\n    Speech.useBank=false; Speech.voiceName=next; Speech.init();\n    e.target.textContent=next===\"male\"?\"Male 🧔\":next===\"female\"?\"Female 🌼\":\"Device 🖥️\";\n    persistSettings();\n    Speech.say(\"Hello, friend! Let's learn together.\");\n  };\n  document.getElementById(\"test\").onclick = ()=>Speech.say(\"Hello, friend! Let's learn together.\");\n  const micRes = document.getElementById(\"micRes\");\n  document.getElementById(\"micTest\").onclick = e=>{\n    if(!Recog.supported){ micRes.textContent = \"This browser can't listen — try Chrome, Edge, or Safari.\"; return; }\n    e.target.textContent = \"👂 Listening…\"; e.target.classList.add(\"listening\");\n    micRes.textContent = \"Say anything now!\";\n    Recog.listen({\n      onSound: ()=>{ micRes.textContent = \"✨ I can hear sound…\"; },\n      onHear: alts=>{\n        e.target.textContent = \"🎤 Test\"; e.target.classList.remove(\"listening\");\n        state.micBroken = false;\n        micRes.innerHTML = \"✅ Working! I heard: <b>“\"+(alts[0]||\"…\")+\"”</b>\";\n        Speech.say(\"I heard you! The microphone works!\");\n      },\n      onFail: err=>{\n        e.target.textContent = \"🎤 Test\"; e.target.classList.remove(\"listening\");\n        if(MIC_BLOCKED.includes(err)){\n          state.micBroken = true;\n          micRes.innerHTML = \"🚫 Blocked. If this is a preview window, <b>download the file and open it in Chrome, Edge, or Safari</b>, then allow the microphone near the address bar.\";\n        }else{\n          micRes.textContent = \"I didn't catch a sound — press Test and speak right away.\";\n        }\n      }\n    });\n  };\n}\n\n/* ===== SOUND COACH (per-sound practice) ===== */\nfunction gymWordsFor(sound){\n  const words = Object.keys(W).map(k=>W[k].w).filter(w=>soundsOf(w).includes(sound));\n  return words.sort((a,b)=>((state.report.wordStats[b]||{}).miss||0)-((state.report.wordStats[a]||{}).miss||0)).slice(0,3);\n}\nfunction renderGym(){\n  stripWrap.hidden = true;\n  if(!Recog.supported || !state.voiceOn || state.micBroken){\n    app.innerHTML = topbar(\"Sound Coach\") + `\n      <div class=\"card scene\"><div class=\"art\">🎤</div>\n        <div class=\"say\">Sound Coach needs the microphone</div>\n        <div class=\"sub\">${!Recog.supported?\"This browser can't listen — try Chrome, Edge, or Safari.\":state.micBroken?\"The microphone was blocked. Download the file and open it in Chrome, Edge, or Safari, then allow the mic.\":\"Turn on Talking practice in Voice Settings first.\"}</div>\n        <button class=\"btn\" onclick=\"go('home')\">Back home</button>\n      </div>`;\n    return;\n  }\n  const tricky = trickySounds();\n  if(!tricky.length){\n    app.innerHTML = topbar(\"Sound Coach\") + `\n      <div class=\"card scene\"><div class=\"art\">🎯✨</div>\n        <div class=\"say\">No tricky sounds spotted yet!</div>\n        <div class=\"sub\">Play the steps and use the microphone. If a sound keeps being hard, I'll notice it and build a warm-up just for it — it will show up here.</div>\n        <button class=\"btn\" onclick=\"go('s1')\">Go practice words →</button>\n      </div>`;\n    return;\n  }\n  const queue = [];\n  tricky.slice(0,3).forEach(s=>gymWordsFor(s).forEach(w=>queue.push({s,w})));\n  state.stage = {queue, i:0, won:0};\n  drawGym();\n}\nfunction drawGym(){\n  const st = state.stage;\n  if(st.i >= st.queue.length){\n    Speech.say(\"Sound star! Your mouth muscles got a great workout!\");\n    const ov = el(`<div class=\"overlay\"><div class=\"panel\">\n        <div class=\"big-em bouncy\">🎯🌟</div><h2>Sound star!</h2>\n        <p>You practiced ${st.queue.length} tricky words. The more you visit the Sound Coach, the easier they get.</p>\n        <button class=\"btn\" id=\"gDone\">Back home</button></div></div>`);\n    document.body.appendChild(ov);\n    ov.querySelector(\"#gDone\").onclick = ()=>{ov.remove();go(\"home\");};\n    return;\n  }\n  const {s,w} = st.queue[st.i];\n  const key = Object.keys(W).find(k=>W[k].w===w);\n  const item = key ? W[key] : {e:\"🗣️\",w,c:\"social\"};\n  app.innerHTML = topbar(\"Sound Coach\") + `\n    <div class=\"progressdots\">${st.queue.map((_,j)=>`<i class=\"${j<st.i?\"on\":\"\"}\"></i>`).join(\"\")}</div>\n    <div class=\"card scene\">\n      <div class=\"art\">${item.e}</div>\n      <div class=\"say\">The “${s}” sound</div>\n      <div class=\"heard\" style=\"max-width:420px\">🎯 ${tipFor(s)}</div>\n      <div class=\"saytarget\">${w}</div>\n      <div style=\"display:flex;gap:10px;flex-wrap:wrap;justify-content:center\">\n        <button class=\"listen\" id=\"gHear\">🔊 Hear the tip</button>\n        <button class=\"mic-btn\" id=\"gTry\">🎤 Practice this word</button>\n      </div>\n      <button class=\"btn ghost\" id=\"gSkip\" style=\"font-size:.95rem;padding:9px 20px\">Skip this word →</button>\n    </div>`;\n  const speakTip = ()=>Speech.say([\"The \"+s+\" sound.\", tipFor(s), \"The word is:\", w]);\n  document.getElementById(\"gHear\").onclick = speakTip;\n  setTimeout(speakTip, 400);\n  document.getElementById(\"gTry\").onclick = ()=>voicePractice(w, ()=>{st.i++; drawGym();});\n  document.getElementById(\"gSkip\").onclick = ()=>{st.i++; drawGym();};\n}\n\n/* ===== PROGRESS REPORT (for parents & therapists) ===== */\nfunction reportText(){\n  const r = state.report;\n  const acc = r.voiceTries ? Math.round(100*r.voiceHits/r.voiceTries) : null;\n  const tricky = trickySounds();\n  const well = Object.entries(r.wordStats).filter(([,x])=>x.ok>0 && x.ok>=x.miss).map(([w])=>w);\n  const work = Object.entries(r.wordStats).filter(([,x])=>x.miss>x.ok).map(([w])=>w);\n  return [\n    \"MY VOICE JOURNEY — SESSION REPORT\",\n    \"Date: \"+new Date().toLocaleString(),\n    \"Session length: ~\"+Math.max(1,Math.round((Date.now()-r.startedAt)/60000))+\" min\",\n    \"\",\n    \"Stars: Step1 \"+state.stars[1]+\"/3 · Step2 \"+state.stars[2]+\"/3 · Step3 \"+state.stars[3]+\"/3 · Step4 \"+state.stars[4]+\"/3\",\n    \"Games finished: \"+Object.values(r.gamesPlayed).reduce((a,b)=>a+b,0),\n    \"Words spoken aloud (credited): \"+state.spokenWords,\n    \"Voice attempts: \"+r.voiceTries+(acc!==null?\" · recognized correctly: \"+acc+\"%\":\"\"),\n    \"\",\n    \"Sounds to target\"+(tricky.length?\":\":\" : none flagged yet\"),\n    ...tricky.map(s=>\"  · /\"+s+\"/ — missed \"+state.sounds[s].miss+\"×, clear \"+state.sounds[s].ok+\"×\"),\n    \"\",\n    \"Words said clearly: \"+(well.join(\", \")||\"—\"),\n    \"Words to keep practicing: \"+(work.join(\", \")||\"—\"),\n    \"\",\n    \"Note: recognition is automated & generous; use as a guide, not a clinical measure.\",\n  ].join(\"\\n\");\n}\nfunction renderReport(){\n  stripWrap.hidden = true;\n  const r = state.report;\n  const acc = r.voiceTries ? Math.round(100*r.voiceHits/r.voiceTries) : null;\n  const mins = Math.max(1, Math.round((Date.now()-r.startedAt)/60000));\n  const tricky = trickySounds();\n  const well = Object.entries(r.wordStats).filter(([,x])=>x.ok>0 && x.ok>=x.miss).map(([w])=>w);\n  const work = Object.entries(r.wordStats).filter(([,x])=>x.miss>x.ok).map(([w])=>w);\n  const games = Object.values(r.gamesPlayed).reduce((a,b)=>a+b,0);\n  app.innerHTML = topbar(\"Progress Report\") + `\n    <div class=\"card\" style=\"text-align:center;color:var(--ink-soft);font-size:.95rem\">\n      📊 For parents, teachers & speech therapists · session so far: <b>${mins} min</b>\n    </div>\n    <div class=\"statgrid\">\n      <div class=\"stat\"><div class=\"n\">${state.stars[1]+state.stars[2]+state.stars[3]+state.stars[4]}/12</div><div class=\"l\">Stars earned</div></div>\n      <div class=\"stat\"><div class=\"n\">${games}</div><div class=\"l\">Games finished</div></div>\n      <div class=\"stat\"><div class=\"n\">${state.spokenWords}</div><div class=\"l\">Words spoken aloud</div></div>\n      <div class=\"stat\"><div class=\"n\">${acc!==null?acc+\"%\":\"—\"}</div><div class=\"l\">Voice attempts recognized</div></div>\n    </div>\n    <div class=\"card\">\n      <h3 class=\"display\" style=\"margin-bottom:6px\">🎯 Sounds to target</h3>\n      ${tricky.length ? tricky.map(s=>`\n        <div class=\"soundrow\">\n          <div class=\"sbadge\">/${s}/</div>\n          <div><b>Missed ${state.sounds[s].miss}× · clear ${state.sounds[s].ok}×</b><br>\n          <span style=\"color:var(--ink-soft);font-size:.93rem\">Cue: ${tipFor(s)}</span></div>\n        </div>`).join(\"\")\n      : `<p style=\"color:var(--ink-soft)\">No repeated trouble sounds detected yet. They appear after the same sound is missed at least twice in talking practice.</p>`}\n      ${tricky.length?`<div style=\"text-align:center;margin-top:10px\"><button class=\"btn ghost\" onclick=\"go('gym')\">Open Sound Coach →</button></div>`:\"\"}\n    </div>\n    <div class=\"card\">\n      <h3 class=\"display\" style=\"margin-bottom:8px\">✅ Words said clearly</h3>\n      <div class=\"chips\">${well.length?well.map(w=>`<span class=\"good-w\">${w}</span>`).join(\"\"):`<span>—</span>`}</div>\n      <h3 class=\"display\" style=\"margin:14px 0 8px\">💪 Words to keep practicing</h3>\n      <div class=\"chips\">${work.length?work.map(w=>`<span class=\"work-w\">${w}</span>`).join(\"\"):`<span>—</span>`}</div>\n    </div>\n    <div class=\"card\" style=\"text-align:center\">\n      <button class=\"btn\" id=\"copyRep\">📋 Copy report</button>\n      <p style=\"color:var(--ink-soft);font-size:.9rem;margin-top:10px\">\n        ⚠️ Progress lives only in this session — copy the report before closing the app.<br>\n        Recognition is automated and intentionally generous; treat it as a guide, not a clinical measure.\n      </p>\n    </div>`;\n  document.getElementById(\"copyRep\").onclick = async ()=>{\n    const txt = reportText();\n    try{ await navigator.clipboard.writeText(txt); toast(\"📋 Report copied — paste it anywhere!\",\"good\"); }\n    catch(e){\n      const ta=document.createElement(\"textarea\"); ta.value=txt; document.body.appendChild(ta);\n      ta.select(); try{document.execCommand(\"copy\"); toast(\"📋 Report copied!\",\"good\");}catch(e2){ toast(\"Couldn't copy — screenshot works too!\",\"try\"); }\n      ta.remove();\n    }\n  };\n}\n\n\n/* ===== PERSISTENT SETTINGS ===== */\nconst SET_KEY=\"mvj_settings_v1\";\nfunction applyDisplaySettings(){\n  document.documentElement.style.fontSize = Math.round(17*(state.textScale||1))+\"px\";\n  document.body.dataset.contrast = state.contrast ? \"high\" : \"\";\n  document.documentElement.style.colorScheme = state.contrast ? \"dark\" : \"light\";\n}\nfunction persistSettings(){\n  try{\n    localStorage.setItem(SET_KEY, JSON.stringify({\n      textScale:state.textScale, contrast:!!state.contrast,\n      voice: Speech.voiceName || \"device\", rate: Speech.rate\n    }));\n  }catch(e){}\n}\nfunction loadSettings(){\n  try{\n    const s = JSON.parse(localStorage.getItem(SET_KEY)||\"{}\");\n    if(s.textScale) state.textScale = Math.min(1.4, Math.max(.85, s.textScale));\n    state.contrast = !!s.contrast;\n    if(s.rate) Speech.rate = s.rate;\n    if(s.voice){ Speech.useBank=false; Speech.voiceName=[\"female\",\"male\",\"device\"].includes(s.voice)?s.voice:\"female\"; Speech.init(); }\n  }catch(e){}\n}\n\n/* ===== CUSTOM PHRASES (saved on this device) ===== */\nconst CUSTOM_KEY = \"mvj_custom_phrases_v1\";\nfunction loadCustom(){\n  try{\n    const raw = localStorage.getItem(CUSTOM_KEY);\n    return raw ? JSON.parse(raw) : [];\n  }catch(e){ return state._customMem || []; }\n}\nfunction saveCustom(list){\n  state._customMem = list;\n  try{ localStorage.setItem(CUSTOM_KEY, JSON.stringify(list)); return true; }\n  catch(e){ return false; }\n}\nfunction addCustomPhrase(text){\n  text = (text||\"\").trim();\n  if(!text) return false;\n  const list = loadCustom();\n  if(list.some(p=>p.t===text)) return true; // already saved\n  list.unshift({t:text, e:\"⭐\"});\n  const persisted = saveCustom(list);\n  if(!persisted) toast(\"Saved for this session — this browser can't keep it after closing.\",\"try\");\n  return true;\n}\nfunction renderCustomBoard(){\n  stripWrap.hidden = true;\n  const list = loadCustom();\n  app.innerHTML = `\n    <div class=\"topbar\">\n      <button class=\"home-btn\" onclick=\"go('home')\">← Back</button>\n      <div class=\"title display\">⭐ My Phrases</div>\n      <div class=\"stars\"></div>\n    </div>\n    ${quickbarHTML()}\n    <div class=\"typebox\">\n      <div class=\"typerow\">\n        <input id=\"custIn\" type=\"text\" maxlength=\"140\" placeholder=\"Add a word or phrase you use often…\" autocomplete=\"off\">\n        <button class=\"saybtn\" id=\"custAdd\">＋ Save</button>\n      </div>\n      <div style=\"color:var(--ink-soft);font-size:.85rem;text-align:center\">Saved on this device · spoken with the device voice</div>\n    </div>\n    <div class=\"phraselist\" id=\"custList\">\n      ${list.length ? list.map((p,i)=>`<button class=\"phrase\" data-pi=\"${i}\">\n          <span class=\"pe\">${p.e}</span><span class=\"pt\">${p.t}</span>\n          <span class=\"pshow\" data-show=\"${i}\" role=\"button\" aria-label=\"Show large\">🪧</span>\n          <span class=\"pshow\" data-del=\"${i}\" role=\"button\" aria-label=\"Delete\">🗑️</span>\n          <span class=\"ps\">🔊</span></button>`).join(\"\")\n        : `<div class=\"card\" style=\"text-align:center;color:var(--ink-soft)\">No saved phrases yet. Add the words and phrases this person uses every day — a nickname, a favorite food, a routine, anything.</div>`}\n    </div>`;\n  wireQuickbar();\n  const refresh = ()=>renderCustomBoard();\n  document.getElementById(\"custAdd\").onclick = ()=>{\n    const inp=document.getElementById(\"custIn\");\n    if(addCustomPhrase(inp.value)){ Speech.say(inp.value.trim()); refresh(); }\n  };\n  document.getElementById(\"custIn\").onkeydown = e=>{ if(e.key===\"Enter\") document.getElementById(\"custAdd\").click(); };\n  app.querySelectorAll(\"#custList .phrase\").forEach(b=>b.onclick=()=>speakPhrase(b, loadCustom()[b.dataset.pi].t));\n  app.querySelectorAll(\"#custList [data-show]\").forEach(s=>s.onclick=e=>{\n    e.stopPropagation(); const ph=loadCustom()[s.dataset.show]; showCard(ph.t, ph.e);\n  });\n  app.querySelectorAll(\"#custList [data-del]\").forEach(d=>d.onclick=e=>{\n    e.stopPropagation();\n    const list=loadCustom(); const ph=list[d.dataset.del];\n    if(confirm('Delete \"'+ph.t+'\"?')){ list.splice(d.dataset.del,1); saveCustom(list); refresh(); }\n  });\n}\nwindow.renderCustomBoard = renderCustomBoard;\n\n/* ===== TYPE & SPEAK ===== */\nfunction typeboxHTML(){\n  return `<div class=\"typebox comm-typebox\">\n    <div class=\"typebox-title\"><h2>Type & Speak</h2><p>Type a message, show it clearly, or say it out loud.</p></div>\n    <div class=\"typerow\">\n      <input id=\"typeIn\" type=\"text\" maxlength=\"140\" placeholder=\"Type anything to say…\" autocomplete=\"off\" aria-label=\"Message to speak\">\n      <button class=\"showbtn\" id=\"typeShow\" aria-label=\"Show message full screen\">🪧 Show Card</button>\n      <button class=\"saybtn\" id=\"typeSay\">🔊 Speak</button>\n    </div>\n    <div class=\"typehist\" id=\"typeHist\"></div>\n  </div>`;\n}\nfunction wireTypebox(){\n  const inp=document.getElementById(\"typeIn\"), btn=document.getElementById(\"typeSay\"), hist=document.getElementById(\"typeHist\");\n  if(!inp) return;\n  const drawHist=()=>{\n    hist.innerHTML=(state.typedHistory||[]).map((t,i)=>\n      `<button data-h=\"${i}\">🔊 ${t}</button><button data-save=\"${i}\" title=\"Save to My Phrases\">⭐</button>`).join(\"\");\n    hist.querySelectorAll(\"button[data-h]\").forEach(b=>b.onclick=()=>Speech.say(state.typedHistory[b.dataset.h]));\n    hist.querySelectorAll(\"button[data-save]\").forEach(b=>b.onclick=()=>{\n      addCustomPhrase(state.typedHistory[b.dataset.save]);\n      toast(\"⭐ Saved to My Phrases\",\"good\");\n    });\n  };\n  const sayIt=()=>{\n    const t=inp.value.trim();\n    if(!t) return;\n    Speech.say(t);\n    state.typedHistory=[t,...(state.typedHistory||[]).filter(x=>x!==t)].slice(0,6);\n    drawHist();\n    inp.select();\n  };\n  btn.onclick=sayIt;\n  document.getElementById(\"typeShow\").onclick=()=>{\n    const t=inp.value.trim(); if(!t) return;\n    state.typedHistory=[t,...(state.typedHistory||[]).filter(x=>x!==t)].slice(0,6);\n    drawHist();\n    showCard(t, \"\");\n  };\n  inp.onkeydown=e=>{ if(e.key===\"Enter\") sayIt(); };\n  drawHist();\n}\n\n/* ===== APHASIA SUPPORT MODE ===== */\nconst APHASIA = {\n  quick: [\n    {t:\"Yes.\", e:\"✅\", bg:\"#E4F0E9\", fg:\"#1D5138\"},\n    {t:\"No.\", e:\"✋\", bg:\"#F6E7E3\", fg:\"#7A2E1D\"},\n    {t:\"Help, please.\", e:\"🆘\", bg:\"#E4EEF0\", fg:\"#14555C\"},\n    {t:\"Wait, please.\", e:\"⏳\", bg:\"#F3EEDF\", fg:\"#6B5200\"},\n  ],\n  cats: [\n    {id:\"aboutme\", name:\"About Me\", e:\"🪪\", sub:\"Share who you are.\", phrases:[\n      {t:\"I have aphasia. My thinking is fine.\", e:\"🧠\"},\n      {t:\"I had a stroke.\", e:\"🫀\"},\n      {t:\"I have difficulty speaking.\", e:\"🗣️\"},\n      {t:\"Yes and no are hard for me. Please ask again.\", e:\"🔄\"},\n      {t:\"I need my parent, guardian, or representative.\", e:\"🧑‍💼\"},\n      {t:\"I do not make decisions without my parent, guardian or representative.\", e:\"⚖️\"},\n      {t:\"I do not answer questions without a parent, guardian, or legal representative.\", e:\"🙅\"},\n      {t:\"I can not sign anything without my guardian or representative.\", e:\"🖊️\"},\n      {t:\"I prefer not to answer without my guardian or representative.\", e:\"🤐\"},\n      {t:\"Please give me time to answer.\", e:\"⏱️\"},\n      {t:\"I need time to think.\", e:\"🤔\"},\n      {t:\"We need to wait.\", e:\"⏳\"},\n      {t:\"I have difficulty following directions without guidance.\", e:\"🧭\"},\n      {t:\"I generally require more information.\", e:\"ℹ️\"},\n      {t:\"I generally require guidance to complete tasks.\", e:\"🤝\"},\n      {t:\"Please speak slowly.\", e:\"🐢\"},\n      {t:\"Please repeat that.\", e:\"🔁\"},\n      {t:\"Can you write it down?\", e:\"✍️\"},\n      {t:\"I understand you.\", e:\"👍\"},\n      {t:\"I don't understand.\", e:\"❓\"},\n    ]},\n    {id:\"needs\", name:\"Quick Needs\", e:\"🙋\", sub:\"Get what you need.\", phrases:[\n      {t:\"I need the bathroom.\", e:\"🚻\"},\n      {t:\"I have soiled myself and need assistance please.\", e:\"🫧\"},\n      {t:\"I'm thirsty.\", e:\"💧\"},\n      {t:\"I'm hungry.\", e:\"🍽️\"},\n      {t:\"I'm tired. I need to rest.\", e:\"😴\"},\n      {t:\"I'm in pain.\", e:\"🤕\"},\n      {t:\"I need my medication.\", e:\"💊\"},\n      {t:\"Please call my family.\", e:\"📞\"},\n      {t:\"I need a doctor.\", e:\"🩺\"},\n      {t:\"I am ready to work.\", e:\"💪\"},\n      {t:\"I am ready for therapy.\", e:\"🧑‍⚕️\"},\n    ]},\n    {id:\"feelings\", name:\"Feelings\", e:\"💬\", sub:\"Share how you feel.\", phrases:[\n      {t:\"I feel good.\", e:\"🙂\"},\n      {t:\"I'm happy.\", e:\"😊\"},\n      {t:\"I'm excited.\", e:\"🤩\"},\n      {t:\"I'm happy to see you.\", e:\"🤗\"},\n      {t:\"I like seeing you.\", e:\"😊\"},\n      {t:\"I love you.\", e:\"❤️\"},\n      {t:\"I like that.\", e:\"👍\"},\n      {t:\"I don't like that.\", e:\"👎\"},\n      {t:\"This is fun.\", e:\"🎉\"},\n      {t:\"That was fun!\", e:\"🥳\"},\n      {t:\"That was dull.\", e:\"😐\"},\n      {t:\"That was boring.\", e:\"🥱\"},\n      {t:\"I feel bad.\", e:\"🙁\"},\n      {t:\"I do not feel well.\", e:\"🤒\"},\n      {t:\"I feel sad.\", e:\"😢\"},\n      {t:\"I am angry.\", e:\"😠\"},\n      {t:\"I'm frustrated.\", e:\"😤\"},\n      {t:\"I'm worried.\", e:\"😟\"},\n      {t:\"I am concerned.\", e:\"😕\"},\n      {t:\"I am confused.\", e:\"😵‍💫\"},\n      {t:\"I am bored.\", e:\"🥱\"},\n      {t:\"I feel alone.\", e:\"🫥\"},\n      {t:\"I am scared.\", e:\"😨\"},\n      {t:\"I saw something that scared me.\", e:\"👁️\"},\n      {t:\"I heard something that scared me.\", e:\"👂\"},\n      {t:\"I am hot.\", e:\"🥵\"},\n      {t:\"I am warm.\", e:\"🌡️\"},\n      {t:\"I am cold.\", e:\"🥶\"},\n    ]},\n    {id:\"safety\", name:\"Safety & Rights\", e:\"🛟\", sub:\"Stay safe and informed.\", phrases:[\n      {t:\"I feel safe.\", e:\"🛡️\"},\n      {t:\"I do not feel safe.\", e:\"⚠️\"},\n      {t:\"I want someone else to help me.\", e:\"🔄\"},\n      {t:\"It is nice here.\", e:\"🌤️\"},\n      {t:\"It is bad here.\", e:\"🌧️\"},\n      {t:\"I do not like it here.\", e:\"🙅\"},\n      {t:\"That is mine.\", e:\"✊\"},\n      {t:\"That is not mine.\", e:\"🙌\"},\n      {t:\"That is yours.\", e:\"👉\"},\n      {t:\"That does not belong to you.\", e:\"⛔\"},\n      {t:\"Please move this out of the way.\", e:\"↔️\"},\n      {t:\"I want to stay.\", e:\"⚓\"},\n      {t:\"I want to leave.\", e:\"🚪\"},\n      {t:\"I am ready to go.\", e:\"🎒\"},\n      {t:\"Let's go.\", e:\"➡️\"},\n    ]},\n    {id:\"painbody\", name:\"Pain & Body\", e:\"🩹\", sub:\"Say where and how it hurts.\", phrases:[\n      {t:\"It hurts here.\", e:\"👉\"},\n      {t:\"My head hurts.\", e:\"🤕\"},\n      {t:\"I have chest pain.\", e:\"❤️‍🩹\"},\n      {t:\"My stomach hurts.\", e:\"🫃\"},\n      {t:\"My back hurts.\", e:\"🧍\"},\n      {t:\"My arm hurts.\", e:\"💪\"},\n      {t:\"My leg hurts.\", e:\"🦵\"},\n      {t:\"The pain is bad.\", e:\"🔴\"},\n      {t:\"The pain is small.\", e:\"🟡\"},\n      {t:\"The pain is sharp.\", e:\"⚡\"},\n      {t:\"The pain is dull.\", e:\"🌫️\"},\n      {t:\"The pain is getting worse.\", e:\"📈\"},\n      {t:\"The pain is getting better.\", e:\"📉\"},\n    ]},\n    {id:\"mobility\", name:\"Mobility\", e:\"🦽\", sub:\"Walking and transfer needs.\", phrases:[\n      {t:\"I can not walk.\", e:\"♿\"},\n      {t:\"I have difficulty walking.\", e:\"🚶\"},\n      {t:\"I am shaky when I stand.\", e:\"🫨\"},\n      {t:\"I am a fall risk.\", e:\"⚠️\"},\n      {t:\"I am a partial lift.\", e:\"🤝\"},\n      {t:\"I am a full lift.\", e:\"🛗\"},\n      {t:\"I can not move my arm.\", e:\"💪\"},\n      {t:\"I can not move certain parts of my body.\", e:\"🧍\"},\n    ]},\n    {id:\"medical\", name:\"Medical\", e:\"🩺\", sub:\"Health and medication.\", phrases:[\n      {t:\"I need my medication.\", e:\"💊\"},\n      {t:\"I have taken my medication.\", e:\"✅\"},\n      {t:\"I have taken some of my medication.\", e:\"🌗\"},\n      {t:\"I have taken all of my medication.\", e:\"💯\"},\n      {t:\"I did not take my medication.\", e:\"⏰\"},\n      {t:\"I do not have my medication.\", e:\"🚫\"},\n      {t:\"I feel sick.\", e:\"🤢\"},\n      {t:\"I feel dizzy.\", e:\"💫\"},\n      {t:\"I have trouble swallowing.\", e:\"🥤\"},\n      {t:\"Call a nurse, please.\", e:\"🔔\"},\n      {t:\"When is my appointment?\", e:\"📅\"},\n    ]},\n    {id:\"out\", name:\"Out & About\", e:\"🏪\", sub:\"Restaurants, shops, travel.\", phrases:[\n      {t:\"Water, please.\", e:\"💦\"},\n      {t:\"Coffee, please.\", e:\"☕\"},\n      {t:\"The bill, please.\", e:\"🧾\"},\n      {t:\"Where is the bathroom?\", e:\"🚻\"},\n      {t:\"How much does it cost?\", e:\"💲\"},\n      {t:\"I need help, please.\", e:\"🙋\"},\n    ]},\n    {id:\"social\", name:\"Social\", e:\"👋\", sub:\"Greetings and courtesy.\", phrases:[\n      {t:\"Hello, how are you?\", e:\"👋\"},\n      {t:\"Thank you.\", e:\"🙏\"},\n      {t:\"Thank you very much.\", e:\"💐\"},\n      {t:\"Excuse me.\", e:\"🙋\"},\n      {t:\"I'm sorry.\", e:\"🙏\"},\n      {t:\"That's okay.\", e:\"👌\"},\n      {t:\"That's good.\", e:\"👍\"},\n      {t:\"That's enough.\", e:\"🛑\"},\n      {t:\"See you later.\", e:\"👋\"},\n      {t:\"Goodbye. See you soon.\", e:\"🫱\"},\n      {t:\"Good morning.\", e:\"🌅\"},\n      {t:\"Good night.\", e:\"🌙\"},\n      {t:\"Nice to meet you.\", e:\"🤝\"},\n      {t:\"Happy birthday!\", e:\"🎂\"},\n      {t:\"Congratulations!\", e:\"🎉\"},\n    ]},\n    {id:\"convo\", name:\"Conversation\", e:\"🗨️\", sub:\"Start and keep it going.\", phrases:[\n      {t:\"Let's talk.\", e:\"💬\"},\n      {t:\"How are you?\", e:\"🙂\"},\n      {t:\"How was your day?\", e:\"🌞\"},\n      {t:\"What did you do today?\", e:\"📆\"},\n      {t:\"Do you have a moment?\", e:\"⏱️\"},\n      {t:\"Could you please assist me?\", e:\"🤝\"},\n      {t:\"Tell me more.\", e:\"👂\"},\n      {t:\"What happened?\", e:\"❔\"},\n      {t:\"What did you do?\", e:\"🫵\"},\n      {t:\"How did you do that?\", e:\"🛠️\"},\n      {t:\"How did that happen?\", e:\"🔍\"},\n      {t:\"What happened after that?\", e:\"⏭️\"},\n      {t:\"What are you going to do?\", e:\"🧭\"},\n      {t:\"What do you plan to do?\", e:\"🗺️\"},\n      {t:\"Did you like that?\", e:\"❤️\"},\n      {t:\"That sounds interesting.\", e:\"🤓\"},\n      {t:\"That sounds entertaining.\", e:\"🎭\"},\n      {t:\"That sounds exciting.\", e:\"🤩\"},\n      {t:\"That sounds amusing.\", e:\"😄\"},\n      {t:\"That sounds disappointing.\", e:\"😞\"},\n      {t:\"That sounds scary.\", e:\"😨\"},\n      {t:\"That sounds dangerous.\", e:\"⚠️\"},\n      {t:\"Do not do that.\", e:\"🛑\"},\n      {t:\"Complete the task please.\", e:\"✅\"},\n      {t:\"I did not complete the task.\", e:\"📋\"},\n      {t:\"I did not finish.\", e:\"⏸️\"},\n      {t:\"I am not finished.\", e:\"⏳\"},\n    ]},\n    {id:\"questions\", name:\"Questions\", e:\"❓\", sub:\"Ask anything.\", phrases:[\n      {t:\"What?\", e:\"❓\"},\n      {t:\"Who?\", e:\"👤\"},\n      {t:\"When?\", e:\"🕐\"},\n      {t:\"Where?\", e:\"📍\"},\n      {t:\"Why?\", e:\"🤔\"},\n      {t:\"Why not?\", e:\"🤷\"},\n      {t:\"How?\", e:\"🛠️\"},\n      {t:\"What time?\", e:\"⏰\"},\n      {t:\"What day?\", e:\"📅\"},\n      {t:\"What is that?\", e:\"👀\"},\n      {t:\"Please explain.\", e:\"💬\"},\n    ]},\n    {id:\"timedays\", name:\"Time & Days\", e:\"📅\", sub:\"Days and times.\", phrases:[\n      {t:\"Today.\", e:\"📍\"},\n      {t:\"Tomorrow.\", e:\"➡️\"},\n      {t:\"Yesterday.\", e:\"⬅️\"},\n      {t:\"Not today.\", e:\"🚫\"},\n      {t:\"Maybe tomorrow.\", e:\"🤞\"},\n      {t:\"In the morning.\", e:\"🌅\"},\n      {t:\"In the afternoon.\", e:\"☀️\"},\n      {t:\"At night.\", e:\"🌙\"},\n      {t:\"Monday.\", e:\"1️⃣\"},\n      {t:\"Tuesday.\", e:\"2️⃣\"},\n      {t:\"Wednesday.\", e:\"3️⃣\"},\n      {t:\"Thursday.\", e:\"4️⃣\"},\n      {t:\"Friday.\", e:\"5️⃣\"},\n      {t:\"Saturday.\", e:\"6️⃣\"},\n      {t:\"Sunday.\", e:\"7️⃣\"},\n    ]},\n    {id:\"daily\", name:\"Daily Life\", e:\"🏠\", sub:\"Home and routines.\", phrases:[\n      {t:\"I want to watch TV.\", e:\"📺\"},\n      {t:\"I want to listen to music.\", e:\"🎵\"},\n      {t:\"I want to go outside.\", e:\"🌳\"},\n      {t:\"I want to go home.\", e:\"🏠\"},\n      {t:\"I want to see my family.\", e:\"👪\"},\n      {t:\"I need a shower.\", e:\"🚿\"},\n      {t:\"Please help me get dressed.\", e:\"👕\"},\n      {t:\"I want to rest.\", e:\"🛋️\"},\n      {t:\"I want to eat now.\", e:\"🍽️\"},\n      {t:\"Please answer the phone.\", e:\"📞\"},\n      {t:\"Call me back later.\", e:\"📲\"},\n      {t:\"Time to eat.\", e:\"🍽️\"},\n      {t:\"I have not eaten.\", e:\"🚫\"},\n      {t:\"I have not eaten enough to be full.\", e:\"🥣\"},\n      {t:\"I did not finish my meal.\", e:\"🍴\"},\n      {t:\"Time to cook.\", e:\"🍳\"},\n      {t:\"Time to shop for groceries.\", e:\"🛒\"},\n      {t:\"I need my clothes.\", e:\"👕\"},\n      {t:\"I need my underwear.\", e:\"🩲\"},\n      {t:\"I need my shoes.\", e:\"👟\"},\n    ]},\n    {id:\"english\", name:\"English Help\", e:\"🌍\", sub:\"Help with English.\", phrases:[\n      {t:\"I am learning English.\", e:\"📖\"},\n      {t:\"How do you say this in English?\", e:\"🗨️\"},\n      {t:\"What does that mean?\", e:\"💭\"},\n      {t:\"Can you spell that, please?\", e:\"🔤\"},\n      {t:\"I don't understand English well.\", e:\"🌐\"},\n      {t:\"Thank you for your patience.\", e:\"🙏\"},\n    ]},\n  ]\n};\nfunction showCard(text, emoji){\n  const size = text.length<=16 ? \"3.4rem\" : text.length<=40 ? \"2.6rem\" : text.length<=80 ? \"2rem\" : \"1.6rem\";\n  const ov = el(`<div class=\"showcard\" role=\"dialog\" aria-label=\"Message card\">\n      <button class=\"sc-close\" aria-label=\"Close\">✕</button>\n      ${emoji?`<div class=\"sc-emoji\">${emoji}</div>`:\"\"}\n      <div class=\"sc-text\" style=\"font-size:${size}\">${text}</div>\n      <div class=\"sc-actions\">\n        <button class=\"btn\" id=\"scSay\" style=\"font-size:1.3rem;padding:16px 34px\">🔊 Say it</button>\n      </div>\n    </div>`);\n  document.body.appendChild(ov);\n  const close=()=>{ Speech.stopAll(); ov.remove(); };\n  ov.querySelector(\".sc-close\").onclick=close;\n  ov.querySelector(\"#scSay\").onclick=()=>Speech.say(text);\n  ov.querySelector(\".sc-text\").onclick=()=>Speech.say(text);\n}\nwindow.showCard = showCard;\nfunction speakPhrase(btn, text){\n  document.querySelectorAll(\".phrase.saying\").forEach(b=>b.classList.remove(\"saying\"));\n  btn.classList.add(\"saying\");\n  Speech.say(text, ()=>btn.classList.remove(\"saying\"));\n}\nfunction quickbarHTML(){\n  return `<div class=\"quickbar\" aria-label=\"Quick communication\">` + APHASIA.quick.map((q,i)=>\n    `<button class=\"quick\" style=\"background:${q.bg};color:${q.fg}\" data-qi=\"${i}\"\n        oncontextmenu=\"event.preventDefault();showCard('${q.t.replace(/'/g,\"\\\\'\")}','${q.e}')\">\n      <span>${q.e}</span><b>${q.t.replace(\", please\",\"\").replace(\".\",\"\")}</b></button>`).join(\"\") + `</div>`;\n}\nfunction wireQuickbar(){\n  document.querySelectorAll(\".quick\").forEach(b=>b.onclick=()=>speakPhrase(b, APHASIA.quick[b.dataset.qi].t));\n}\nfunction renderAphasiaHome(){\n  stripWrap.hidden = true;\n  app.innerHTML = `<div class=\"home-shell aphasia-home\">\n    ${mainHeader()}\n    <section class=\"hero-panel\"><div class=\"hero-center\">\n      <div class=\"hero-symbol\"><img class=\"hero-voice-icon\" src=\"${OFFICIAL_VOICE_ICON}\" alt=\"Voice\"></div><h1>My Words</h1>\n      <p>Tap a phrase, type a message, or build what you want to say.</p>\n    </div></section>\n    ${mainModePicker('aphasia')}\n    ${quickbarHTML()}\n    ${typeboxHTML()}\n    <div class=\"catgrid\">\n      <button class=\"catcard\" onclick=\"go('customboard')\" style=\"border-style:dashed\"><span class=\"ce\">⭐</span><span class=\"cn\">My Phrases</span><span class=\"cs\">Your own saved words.</span></button>\n      ${APHASIA.cats.map(c=>`<button class=\"catcard\" onclick=\"openAphCat('${c.id}')\"><span class=\"ce\">${c.e}</span><span class=\"cn\">${c.name}</span><span class=\"cs\">${c.sub||\"\"}</span></button>`).join(\"\")}\n    </div>\n    <div class=\"aph-actions\">\n      <button class=\"path\" onclick=\"go('board')\"><div class=\"badge\" style=\"background:#F1ECFF\">🎛️</div><div class=\"tx\"><h3>Word Board</h3><p>Build your own message, word by word.</p></div><div class=\"st\">›</div></button>\n      <button class=\"path\" onclick=\"go('settings')\"><div class=\"badge\" style=\"background:#EEF3F8\">⚙️</div><div class=\"tx\"><h3>Voice & Accessibility</h3><p>Voice, speed, text size and contrast.</p></div><div class=\"st\">›</div></button>\n    </div>\n  </div>`;\n  wireQuickbar();wireTypebox();\n}\nfunction openAphCat(id){ state.aphCat=id; go(\"aphboard\"); }\nwindow.openAphCat = openAphCat;\nfunction renderAphBoard(){\n  stripWrap.hidden = true;\n  const cat = APHASIA.cats.find(c=>c.id===state.aphCat) || APHASIA.cats[0];\n  app.innerHTML = `\n    <div class=\"topbar\">\n      <button class=\"home-btn\" onclick=\"go('home')\">← Back</button>\n      <div class=\"title display\">${cat.e} ${cat.name}</div>\n      <div class=\"stars\"></div>\n    </div>\n    ${quickbarHTML()}\n    <div class=\"phraselist\">\n      ${cat.phrases.map((p,i)=>`<button class=\"phrase\" data-pi=\"${i}\">\n        <span class=\"pe\">${p.e}</span><span class=\"pt\">${p.t}</span>\n        <span class=\"pshow\" data-show=\"${i}\" role=\"button\" aria-label=\"Show large\">🪧</span>\n        <span class=\"ps\">🔊</span></button>`).join(\"\")}\n    </div>`;\n  wireQuickbar();\n  app.querySelectorAll(\".phrase\").forEach(b=>b.onclick=()=>speakPhrase(b, cat.phrases[b.dataset.pi].t));\n  app.querySelectorAll(\".pshow\").forEach(s=>s.onclick=(e)=>{\n    e.stopPropagation();\n    const ph=cat.phrases[s.dataset.show];\n    showCard(ph.t, ph.e);\n  });\n}\n\n/* ---------- boot ---------- */\nwindow.go = go;\nwindow.switchMode = switchMode;\nloadSettings();\nsetMode(\"kids\");\napplyDisplaySettings();\ngo(\"home\");\n</script>\n<a class=\"ecc-host-link\" href=\"/learning\">ECCOOZS Learning Apps</a></body>\n</html>\n";

export type VoiceJourneyAudience = "adult" | "youth";

export function buildVoiceJourneyHtml(audience: VoiceJourneyAudience) {
  const mode = audience === "youth" ? "kids" : "adult";
  const title = audience === "youth" ? "My Voice Journey Youth — Learning to Speak" : "My Voice Journey — English Practice & My Words";
  const audienceCss = audience === "youth"
    ? `.modepick{display:none!important}`
    : `.modepick .mode:first-child{display:none!important} .modepick{grid-template-columns:repeat(2,minmax(0,1fr))!important}`;

  const withAssets = voiceJourneyAssets.reduce((html, src, index) => {
    const name = index === 0 ? "voice-icon" : index === 1 ? "leo-waving" : "leo-seated";
    return html.replaceAll(`/learning-assets/my-voice-journey/${name}.png`, src);
  }, baseHtml);

  return withAssets
    .replace("<title>My Voice Journey — Learn to Say It</title>", `<title>${title}</title>`)
    .replace("setMode(\"kids\");", `setMode(\"${mode}\");`)
    .replace("</head>", `<style id=\"eccoozs-audience-lock\">${audienceCss}</style></head>`);
}
